<p><label>Start <input id="start" type="range" min="0" max="1000" value="0"></label> <label>End <input id="end" type="range" min="0" max="1000" value="1000"></label></p>
<canvas id="plot" width="1600" height="380" aria-label="Performance timeline"></canvas><p id="detail"></p><h2>Sampled renderer stages</h2><div id="stages"></div><details><summary>Structured analysis and limitations</summary><pre id="summary"></pre></details>
<script>
