def executable_inputs(
    launch: dict[str, object], root: Path, profile: Path | None = None
) -> dict[str, str]:
    paths: set[Path] = set()
    pending = list(launch["argv"]) if isinstance(launch["argv"], list) else []
    visited: set[str] = set()
    while pending:
        token = str(pending.pop())
        if token.startswith("@") and token not in visited:
            visited.add(token)
            path = Path(token[1:])
            paths.add(path)
            pending.extend(shlex.split(path.read_text(), comments=True))
        else:
            if token.startswith("-D") and "=" in token:
                candidate = Path(token.split("=", 1)[1])
                if candidate.is_absolute() and candidate.is_file():
                    paths.add(candidate)
            for piece in token.split(os.pathsep):
                path = Path(piece)
                if path.is_absolute() and path.is_file():
                    paths.add(path)
                elif path.is_absolute() and path.is_dir():
                    paths.update(
                        member for member in path.rglob("*") if member.is_file()
                    )
    legacy = root / "build/moddev/developmentLegacyClasspath.txt"
    paths.add(legacy)
    paths.update(Path(line) for line in legacy.read_text().splitlines() if line)
    paths.update((root / "shaderlod_host").glob("*.py"))
    paths.update(
        path
        for path in (root / "shaderlod_host/templates").rglob("*")
        if path.is_file()
    )
    if profile is not None:
        paths.update((profile / "mods").glob("*.jar"))
        paths.update(
            path for path in (profile / "resourcepacks").rglob("*") if path.is_file()
        )
    for directory in [
        root / "build/classes/java",
        root / "build/resources",
        root / "dependencies/runtime",
    ]:
        paths.update(path for path in directory.rglob("*") if path.is_file())
    return {
        str(path): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in sorted(paths)
        if path.is_file()
    }


PROBE_OUTPUTS = (
    "shaderlod-functional.json",
    "shaderlod-functional.png",
    "shaderlod-functional-identity.png",
)


def preserve_outputs(profile: Path, destination: Path) -> dict[str, str]:
    preserved: dict[str, str] = {}
    for name in PROBE_OUTPUTS:
        source = profile / name
        if source.is_file():
            destination.mkdir(parents=True, exist_ok=True)
            preserved[name] = hashlib.sha256(source.read_bytes()).hexdigest()
            shutil.move(source, destination / name)
    return preserved


def read_functional(path: Path) -> tuple[dict[str, object] | None, str | None]:
    try:
        observed = json.loads(path.read_bytes()) if path.exists() else None
        if observed is not None and not isinstance(observed, dict):
            raise ValueError("functional output must be an object")
        return observed, None
    except (OSError, ValueError) as error:
        return None, str(error)


def attempt_receipt(requested: Path | None, repository: Path, mode: str) -> Path:
    if requested is None:
        stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
        requested = evidence_root() / "attempts" / f"{stamp}-{mode}.json"
    resolved = requested.resolve()
    if resolved.is_relative_to(repository.resolve()):
        raise ValueError(
            "receipts belong outside the repository; omit --receipt to use "
            + str(evidence_root() / "attempts")
        )
    if resolved.exists() or resolved.with_suffix("").exists():
        raise ValueError("receipt already exists; choose a new --receipt or omit it")
    resolved.parent.mkdir(parents=True, exist_ok=True)
    return resolved


def benchmark_session(
    launch_path: Path,
    profile: Path,
    display: Path,
    session: Path,
    ownership: Path,
    timeout: int,
    world: str = "ShaderLOD-Smoke",
    ancestor: tuple[int, str] | None = None,
    telemetry_enabled: bool = False,
    without_shaderlod: bool = False,
) -> int:
    if sys.platform not in {"linux", "win32"} or not 1 <= timeout <= 14400:
        raise ValueError("Linux/Windows session with 1–14400 second deadline required")
    root = Path(__file__).resolve().parents[1]
    if session.exists() or session.resolve().is_relative_to(root):
        raise ValueError("fresh external session directory required")
    if not world or world in {".", ".."} or "/" in world or "\\" in world:
        raise ValueError("single prepared world name required")
    if not profile.is_dir() or not (profile / "saves" / world).is_dir():
        raise ValueError("prepared profile and selected world required")
    launch = json.loads(launch_path.read_bytes())
    if not isinstance(launch.get("argv"), list) or not all(
        isinstance(a, str) for a in launch["argv"]
    ):
        raise ValueError("invalid launch argv")
    argv = list(launch["argv"])
    if "-cp" not in argv:
        raise ValueError("explicit classpath launch required")
    position = argv.index("-cp")
    argv[position:position] = [
        "-Dshaderlod.functionalProbe=false",
        "-Dshaderlod.benchmarkDirectory=" + str(session.resolve()),
    ]
    profile = profile.resolve(strict=True)
    shipping = Path(launch["shipping_jar"])
    import zipfile

    with zipfile.ZipFile(shipping) as archive:
        for relative in (
            "build/classes/java/main",
            "build/classes/java/benchmarkCore",
            "build/resources/main",
        ):
            for compiled in (root / relative).rglob("*"):
                if not compiled.is_file():
                    continue
                member = compiled.relative_to(root / relative).as_posix()
                if (
                    member not in archive.namelist()
                    or archive.read(member) != compiled.read_bytes()
                ):
                    raise ValueError(
                        "shipping JAR differs from compiled classes/resources; build jar before opening session"
                    )
    environment = (
        worker_environment() if os.name == "nt" else display_environment(display)
    )
    environment.update(launch["environment"])
    with BusyRefusal(ownership, socket.gethostname() + ":gpu:0"):
        recover_profile_artifact(profile)
        session.mkdir(parents=True)
        if without_shaderlod:
            from shaderlod_host.storage import publish_bytes

            resource = (
                session / "library-resources/META-INF/shaderlod/primary.properties"
            )
            publish_bytes(
                resource,
                (
                    root / "build/resources/main/META-INF/shaderlod/primary.properties"
                ).read_bytes(),
            )
            library = session / "library-classes"
            for relative in (
                "build/classes/java/main",
                "build/classes/java/benchmarkCore",
            ):
                for compiled in (root / relative).rglob("*.class"):
                    library_member = compiled.relative_to(root / relative)
                    if (
                        library_member.as_posix()
                        != "com/pp/shaderlod/integration/ShaderLod.class"
                    ):
                        publish_bytes(library / library_member, compiled.read_bytes())
            rewritten = []
            for token in argv:
                if token.startswith("-Dfml.modFolders="):
                    token = (
                        "-Dfml.modFolders="
                        + os.pathsep.join(
                            entry
                            for entry in token.split("=", 1)[1].split(os.pathsep)
                            if not entry.startswith("shaderlod%%")
                        )
                        + os.pathsep
                        + "shaderlod_dev%%"
                        + str(library)
                        + os.pathsep
                        + "shaderlod_dev%%"
                        + str(session / "library-resources")
                    )
                rewritten.append(token)
            argv = rewritten
            classpath = argv.index("-cp") + 1
            argv[classpath] = os.pathsep.join(
                [str(session / "library-resources"), str(library)]
                + [
                    entry
                    for entry in argv[classpath].split(os.pathsep)
                    if entry
                    not in {
                        str(root / "build/resources/main"),
                        str(root / "build/classes/java/main"),
                        str(root / "build/classes/java/benchmarkCore"),
                    }
                ]
            )
            legacy = session / "native-legacy-classpath.txt"
            publish_bytes(
                legacy,
                (
                    "\n".join(
                        entry
                        for entry in (
                            root / "build/moddev/developmentLegacyClasspath.txt"
                        )
                        .read_text()
                        .splitlines()
                        if entry
                        not in {
                            str(root / "build/resources/main"),
                            str(root / "build/classes/java/main"),
                            str(root / "build/classes/java/benchmarkCore"),
                        }
                    )
                    + "\n"
                ).encode(),
            )
            argv[argv.index("-cp") : argv.index("-cp")] = [
                "-DlegacyClassPath.file=" + str(legacy)
            ]
            environment.pop("MOD_CLASSES", None)
        found_world = False
        for index, token in enumerate(argv):
            if token.startswith("@"):
                args = shlex.split(Path(token[1:]).read_text(), comments=True)
                if "--quickPlaySingleplayer" in args:
                    position = args.index("--quickPlaySingleplayer") + 1
                    if position >= len(args):
                        raise ValueError("missing quick-play world argument")
                    args[position] = world
                    from shaderlod_host.storage import publish_bytes

                    frozen = session / "world-program-args.txt"
                    publish_bytes(
                        frozen,
                        (
                            "\n".join(
                                '"' + a.replace("\\", "\\\\").replace('"', '\\"') + '"'
                                for a in args
                            )
                            + "\n"
                        ).encode(),
                    )
                    argv[index] = "@" + str(frozen)
                    found_world = True
        if not found_world:
            raise ValueError("launch must declare one quick-play world")
        launch = dict(launch, argv=argv)
        publish(session / "launch.json", launch)
        launch_path = session / "launch.json"
        with profile_artifact(profile, shipping, session, without_shaderlod):
            from shaderlod_host.storage import snapshot_inputs

            snapshot_inputs(root, session / "inputs.tar")
            before = executable_inputs(launch, root, profile)
            with (session / "client.log").open("xb") as log:
                worker = subprocess.Popen(
                    [
                        sys.executable,
                        "-m",
                        "shaderlod_host.worker",
                        str(time.monotonic() + timeout),
                        str(os.getpid()),
                        birth(os.getpid()),
                        json.dumps(argv),
                        str(session / "child.json"),
                        "session",
                    ]
                    + (
                        []
                        if ancestor is None
                        else [json.dumps({"pid": ancestor[0], "birth": ancestor[1]})]
                    ),
                    cwd=profile,
                    env=worker_environment(environment),
                    stdout=log,
                    stderr=subprocess.STDOUT,
                    stdin=subprocess.DEVNULL,
                )
                publish(
                    session / "session.json",
                    {
                        "schema": "shaderlod-session-v1",
                        "host": socket.gethostname(),
                        "boot": boot(),
                        "owner_pid": os.getpid(),
                        "owner_birth": birth(os.getpid()),
                        "profile": str(profile.resolve()),
                        "world": world,
                        "launch": str(launch_path.resolve()),
                        "executable_inputs": before,
                        "shaderlod_mode": "absent"
                        if without_shaderlod
                        else "installed",
                        "build_sha256": hashlib.sha256(
                            shipping.read_bytes()
                        ).hexdigest(),
                        "instrumentation": {
                            "telemetry": "1hz" if telemetry_enabled else "disabled",
                            "frames": "complete-entry-v1",
                        },
                        "input_snapshot_sha256": hashlib.sha256(
                            (session / "inputs.tar").read_bytes()
                        ).hexdigest(),
                        "timeout_seconds": timeout,
                        "capabilities": [
                            "status",
                            "capture",
                            "select",
                            "restore",
                            "prepare",
                            "screenshot",
                            "close",
                            "validate",
                            "recover",
                        ],
                        "qualification": "unqualified development session",
                        "child_record": str(session / "child.json"),
                    },
                )
                try:
                    telemetry_stop = threading.Event()
                    telemetry_errors: list[str] = []
                    telemetry = (
                        threading.Thread(
                            target=record_telemetry,
                            args=(session, telemetry_stop, telemetry_errors),
                            daemon=True,
                        )
                        if telemetry_enabled
                        else None
                    )
                    if telemetry is not None:
                        telemetry.start()
                    try:
                        status = worker.wait(timeout=timeout + 5)
                    except KeyboardInterrupt:
                        status = 130
                    finally:
                        telemetry_stop.set()
                        if telemetry is not None:
                            telemetry.join(timeout=3)
                finally:
                    if worker.poll() is None:
                        worker.terminate()
                        worker.wait(timeout=3)
                unchanged = before == executable_inputs(launch, root, profile)
        publish(
            session / "closed.json",
            {
                "schema": "shaderlod-session-close-v1",
                "returncode": status,
                "inputs_unchanged": unchanged,
                "profile_artifact_restored": True,
                "telemetry_errors": telemetry_errors,
                "telemetry_stopped": telemetry is None or not telemetry.is_alive(),
                "restoration": "profile artifact restored; shader/world state is established by acknowledged close and recovery journals",
                "shader_recovery_pending": (
                    profile / "shaderlod-recovery.json"
                ).exists(),
                "world_recovery_pending": (
                    profile / "shaderlod-benchmark-world.json"
                ).exists(),
            },
        )
        return status


def record_telemetry(
    session: Path, stopping: threading.Event, errors: list[str]
) -> None:
    from shaderlod_host.telemetry import NvidiaSensors, host_sample

    sensors = NvidiaSensors()
    started = time.monotonic_ns()
    index = 0
    try:
        while not stopping.is_set():
            index += 1
            sensor_started = time.perf_counter_ns()
            child = (
                json.loads((session / "child.json").read_bytes())
                if (session / "child.json").exists()
                else None
            )
            record = host_sample(None if child is None else child["pid"])
            record["schema"] = "shaderlod-telemetry-v1"
            record["elapsed_ns"] = time.monotonic_ns() - started
            record["unix_ns"] = time.time_ns()
            record["gpu"] = sensors.sample()
            record["sample_cost_ns"] = time.perf_counter_ns() - sensor_started
            publish(session / "telemetry" / (str(index) + ".json"), record)
            stopping.wait(1)
    except (OSError, ValueError, AttributeError) as error:
        errors.append(str(error))
    finally:
        sensors.close()


def recover_profile_artifact(profile: Path) -> dict[str, object] | None:
    from shaderlod_host.storage import restore_profile_artifact

    marker = profile / "shaderlod-benchmark-profile.json"
    if not marker.exists():
        return None
    record = json.loads(marker.read_bytes())
    previous = Path(record["session"])
    metadata = json.loads((previous / "session.json").read_bytes())
    if (
        metadata.get("host") != socket.gethostname()
        or Path(metadata["profile"]).resolve() != profile.resolve()
    ):
        raise ValueError("foreign profile-artifact recovery owner")
    for pid, identity in [(metadata["owner_pid"], metadata["owner_birth"])]:
        if metadata["boot"] == boot():
            try:
                if birth(pid) == identity:
                    raise ValueError("profile-artifact owner is still live")
            except (OSError, ProcessLookupError):
                pass
    child = json.loads((previous / "child.json").read_bytes())
    if child.get("host") != metadata["host"] or child.get("boot") != metadata["boot"]:
        raise ValueError("profile recovery child identity disagreement")
    if child["boot"] == boot():
        try:
            if birth(child["pid"]) == child["birth"]:
                raise ValueError("owned client still live; profile recovery refused")
        except (OSError, ProcessLookupError):
            pass
    restore_profile_artifact(profile, record)
    outcome: dict[str, object] = {
        "schema": "shaderlod-profile-recovery-v1",
        "artifact_restored": True,
        "previous_session": str(previous),
        "world_journal_pending": (profile / "shaderlod-benchmark-world.json").exists(),
    }
    publish(previous / "profile-recovery.json", outcome)
    return outcome


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Bounded Asahi functional execution, no performance study"
    )
    parser.add_argument("--launch", type=Path, required=True)
    parser.add_argument("--profile", type=Path)
    parser.add_argument("--without-dh", action="store_true")
    parser.add_argument("--native-control", action="store_true")
    parser.add_argument("--shipping-jar", type=Path)
    parser.add_argument("--display", type=Path, required=True)
    parser.add_argument("--receipt", type=Path)
    parser.add_argument("--ownership-root", type=Path, required=True)
    parser.add_argument("--timeout", type=int, default=180)
    args = parser.parse_args()
    if sys.platform != "linux" or not 1 <= args.timeout <= 600:
        parser.error("Linux and bounded 1–600 second timeout required")
    launch = json.loads(args.launch.read_bytes())
    argv = launch["argv"]
    if not isinstance(argv, list) or not all(isinstance(a, str) for a in argv):
        raise ValueError("invalid argument vector")
    if args.shipping_jar is not None:
        if args.native_control or args.shipping_jar.is_symlink():
            raise ValueError(
                "shipping probe requires a regular JAR and development probe"
            )
        root = Path(__file__).resolve().parents[1]
        rewritten = []
        for item in argv:
            if item.startswith("-Dfml.modFolders="):
                entries = [
                    entry
                    for entry in item.split("=", 1)[1].split(":")
                    if not entry.startswith("shaderlod%%")
                ]
                rewritten.append("-Dfml.modFolders=" + ":".join(entries))
            else:
                rewritten.append(item)
        argv = rewritten
        if "-cp" in argv:
            position = argv.index("-cp") + 1
            excluded = {
                str(root / "build/classes/java/main"),
                str(root / "build/resources/main"),
            }
            argv[position] = ":".join(
                item for item in argv[position].split(":") if item not in excluded
            )
        launch["argv"] = argv
    if args.native_control:
        argv = [item for item in argv if not item.startswith("-Dfml.modFolders=")]
        if "-cp" in argv:
            position = argv.index("-cp") + 1
            root = Path(__file__).resolve().parents[1]
            argv[position] = ":".join(
                item
                for item in argv[position].split(":")
                if not item.startswith(str(root / "build/classes"))
                and not item.startswith(str(root / "build/resources"))
            )
        launch["argv"] = argv
    mode = (
        "native-control"
        if args.native_control
        else "without-dh"
        if args.without_dh
        else "dh"
    )
    receipt = attempt_receipt(args.receipt, Path(__file__).resolve().parents[1], mode)
    profile = (args.profile or Path(launch["cwd"])).resolve(strict=True)
    if (profile / "shaderlod-functional.json").exists():
        raise ValueError(
            "earlier probe outputs remain in "
            + str(profile)
            + "; move shaderlod-functional* under "
            + str(evidence_root())
            + " before a new attempt"
        )
    environment = display_environment(args.display)
    environment.update(launch["environment"])
    with BusyRefusal(args.ownership_root, socket.gethostname() + ":gpu:0"):
        root = Path(__file__).resolve().parents[1]
        lock = json.loads((root / "dependencies/runtime.lock.json").read_bytes())
        mods = profile / "mods"
        mods.mkdir(exist_ok=True)
        artifacts = {
            key: value
            for key, value in lock["artifacts"].items()
            if not (args.without_dh and key == "distanthorizons")
        }
        expected = {item["filename"] for item in artifacts.values()}
        attempt_directory = receipt.with_suffix("")
        attempt_directory.mkdir(parents=True)
        publish(
            attempt_directory / "session.json",
            {
                "host": socket.gethostname(),
                "boot": boot(),
                "owner_pid": os.getpid(),
                "owner_birth": birth(os.getpid()),
                "profile": str(profile),
            },
        )
        artifact_context = (
            profile_artifact(profile, args.shipping_jar, attempt_directory)
            if args.shipping_jar is not None
            else nullcontext()
        )
        with artifact_context:
            shipping = None
            if args.shipping_jar is not None:
                shipping = {
                    "filename": args.shipping_jar.name,
                    "sha256": hashlib.sha256(
                        args.shipping_jar.read_bytes()
                    ).hexdigest(),
                }
                expected.add(args.shipping_jar.name)

            if any(p.name not in expected for p in mods.iterdir()):
                raise ValueError(
                    "unmanaged profile mod; preserve and resolve before launch"
                )
            for item in artifacts.values():
                payload = (
                    root / "dependencies/runtime" / item["filename"]
                ).read_bytes()
                if hashlib.sha256(payload).hexdigest() != item["hashes"]["sha256"]:
                    raise ValueError("runtime mod identity disagreement")
                target = mods / item["filename"]
                if target.exists():
                    if target.is_symlink() or target.read_bytes() != payload:
                        raise ValueError("profile mod drift")
                else:
                    target.write_bytes(payload)
            before = executable_inputs(launch, root, profile)
            started = time.monotonic()
            with receipt.with_suffix(".log").open("xb") as log:
                worker = subprocess.Popen(
                    [
                        sys.executable,
                        "-m",
                        "shaderlod_host.worker",
                        str(time.monotonic() + args.timeout),
                        str(os.getpid()),
                        birth(os.getpid()),
                        json.dumps(argv),
                        str(receipt.with_suffix("") / "child.json"),
                        "functional",
                    ],
                    cwd=profile,
                    env=worker_environment(environment),
                    stdin=subprocess.DEVNULL,
                    stdout=log,
                    stderr=subprocess.STDOUT,
                )
                try:
                    status = worker.wait(timeout=args.timeout + 5)
                finally:
                    if worker.poll() is None:
                        worker.terminate()
                        worker.wait(timeout=3)
                functional = profile / "shaderlod-functional.json"
                observed, contract_error = read_functional(functional)
                if observed is not None:
                    pin = json.loads(
                        (root / "dependencies/primary-pack.json").read_bytes()
                    )
                    try:
                        observed = verify_functional(
                            observed,
                            profile,
                            pin["filename"],
                            pin["sha256"],
                            not args.without_dh,
                        )
                    except (OSError, ValueError) as error:
                        contract_error = str(error)
                outputs = preserve_outputs(profile, receipt.with_suffix(""))
                result = {
                    "schema": "shaderlod-live-attempt-v1",
                    "platform": sys.platform,
                    "scope": "live-functional only",
                    "returncode": status,
                    "elapsed_seconds": time.monotonic() - started,
                    "java_sha256": hashlib.sha256(
                        Path(argv[0]).read_bytes()
                    ).hexdigest(),
                    "launch_sha256": hashlib.sha256(
                        args.launch.read_bytes()
                    ).hexdigest(),
                    "functional": observed,
                    "dh_mode": "absent" if args.without_dh else "enabled",
                    "native_control": args.native_control,
                    "shipping_jar": shipping,
                    "profile": str(profile),
                    "outputs": {
                        "directory": str(receipt.with_suffix("")),
                        "sha256": outputs,
                    },
                    "executable_inputs": before,
                    "inputs_unchanged": before
                    == executable_inputs(launch, root, profile),
                    "outcome": "PASS"
                    if status == 0
                    and observed is not None
                    and observed.get("outcome") == "PASS"
                    else "FAIL",
                    "limits": "Advisory participating-owner exclusion; ambient occupancy must be checked before launch; no image-equivalence/performance qualification",
                }
                if contract_error is not None:
                    result["outcome"] = "FAIL"
                    result["contract_failure"] = contract_error
                if result["inputs_unchanged"] is not True:
                    result["outcome"] = "FAIL"
                    result["identity_failure"] = "Executable input drift"
                publish(receipt, result)
                print("RECEIPT: " + str(receipt))
                print(
                    json.dumps(
                        {
                            key: result[key]
                            for key in (
                                "schema",
                                "scope",
                                "outcome",
                                "returncode",
                                "elapsed_seconds",
                            )
                        },
                        sort_keys=True,
                    )
                )
                return 0 if result["outcome"] == "PASS" else 1


if __name__ == "__main__":
    sys.exit(main())


def prepare_windows_runtime(
    legacy: Path, canonical_profile: Path, root: Path
) -> dict[str, object]:
    from shaderlod_host.storage import copytree, publish_bytes, replace_bytes

    if os.name != "nt":
        raise ValueError("native Windows preparation required")
    profile = root / "run-benchmark"
    copytree(canonical_profile, profile, 1073741824)
    python = root / "tools/python"
    copytree(legacy.parent / "tools/python", python, 268435456)
    for pth in python.glob("python*._pth"):
        replace_bytes(pth, pth.read_bytes() + b"\n" + str(root).encode() + b"\n")
    lock = json.loads((root / "dependencies/runtime.lock.json").read_bytes())
    mods = profile / "mods"
    mods.mkdir(exist_ok=True)
    for key, item in lock["artifacts"].items():
        if key == "distanthorizons":
            continue
        payload = (root / "dependencies/runtime" / item["filename"]).read_bytes()
        if hashlib.sha256(payload).hexdigest() != item["hashes"]["sha256"]:
            raise ValueError("runtime artifact hash mismatch")
        publish_bytes(mods / item["filename"], payload)
    pin = json.loads((root / "dependencies/primary-pack.json").read_bytes())
    pack = root / "dependencies/runtime" / pin["filename"]
    if hashlib.sha256(pack.read_bytes()).hexdigest() != pin["sha256"]:
        raise ValueError("primary pack mismatch")
    publish_bytes(profile / "shaderpacks" / pin["filename"], pack.read_bytes())
    build = root / "build/moddev"
    build.mkdir(parents=True, exist_ok=True)
    jars = [
        line
        for line in (legacy / "build/moddev/clientLodOnLegacyClasspath.txt")
        .read_text()
        .splitlines()
        if line.lower().endswith(".jar")
    ]
    artifacts = legacy / "build/moddev/artifacts"
    jars = [
        str(artifacts / ("neoforge-" + lock["neoforge"] + suffix))
        for suffix in (".jar", "-client-extra-aka-minecraft-resources.jar")
    ] + jars
    if not jars or not all(Path(line).is_file() for line in jars):
        raise ValueError("legacy runtime dependencies unavailable")
    publish_bytes(
        build / "developmentLegacyClasspath.txt", ("\n".join(jars) + "\n").encode()
    )
    program = (
        (legacy / "build/moddev/clientLodOnRunProgramArgs.txt")
        .read_text()
        .split("# User Supplied Program Arguments")[0]
    )
    publish_bytes(
        build / "benchmarkRunProgramArgs.txt",
        (program + "\n--quickPlaySingleplayer\nShaderLOD-Smoke\n").encode(),
    )
    java = next((legacy.parent / "tools/java").glob("*/bin/java.exe"))
    classpaths = (
        [
            str(root / "build/classes/java" / name)
            for name in ("main", "devClient", "benchmarkCore")
        ]
        + [str(root / "build/resources" / name) for name in ("main", "devClient")]
        + jars
    )
    manifest: dict[str, object] = {
        "shipping_jar": str(root / "build/libs/shaderlod-0.1.0.jar"),
        "argv": [
            str(java),
            "@" + str(legacy / "build/moddev/clientLodOnRunVmArgs.txt"),
            "-Dfml.modFolders="
            + ";".join(
                mod + "%%" + str(root / suffix)
                for mod, suffix in [
                    ("shaderlod", "build/classes/java/main"),
                    ("shaderlod", "build/resources/main"),
                    ("shaderlod_dev", "build/classes/java/devClient"),
                    ("shaderlod_dev", "build/resources/devClient"),
                ]
            ),
            "-cp",
            ";".join(classpaths),
            "@" + str(build / "benchmarkRunProgramArgs.txt"),
        ],
        "cwd": str(profile),
        "environment": {},
    }
    publish(build / "windows-launch.json", manifest)
    return {
        "schema": "shaderlod-windows-preparation-v1",
        "launch": str(build / "windows-launch.json"),
        "profile": str(profile),
        "python": str(python / "python.exe"),
        "legacy_inputs_preserved": True,
    }


def execute_campaign(
    campaign: object,
    launch: Path,
    profile: Path,
    display: Path,
    ownership: Path,
    output: Path,
    world: str,
    resume: bool = False,
    control: Path | None = None,
) -> dict[str, object]:
    with BusyRefusal(output.parent / (output.name + "-ownership"), "campaign"):
        return campaign_attempts(
            campaign,
            launch,
            profile,
            display,
            ownership,
            output,
            world,
            resume,
            control,
        )


def campaign_attempts(
    campaign: object,
    launch: Path,
    profile: Path,
    display: Path,
    ownership: Path,
    output: Path,
    world: str,
    resume: bool,
    control: Path | None,
) -> dict[str, object]:
    from shaderlod_host.assessment import assess
    from shaderlod_host.benchmark import session_command, wait_ready
    from shaderlod_host.campaign import Campaign
    from shaderlod_host.comparison import execute_comparison

    if not isinstance(campaign, Campaign):
        raise ValueError("decoded campaign required")
    root = Path(__file__).resolve().parents[1]
    input_identity: dict[str, object] = {
        "inputs": executable_inputs(json.loads(launch.read_bytes()), root, profile),
        "profile": str(profile.resolve()),
        "world": world,
    }
    if resume:
        if (
            (output / "result.json").exists()
            or json.loads((output / "campaign.json").read_bytes()) != campaign.wire()
            or json.loads((output / "campaign-inputs.json").read_bytes())
            != input_identity
        ):
            raise ValueError(
                "resume requires the same unfinished frozen plan, source, profile and world"
            )
    else:
        if output.exists():
            raise ValueError(
                "fresh campaign output required; use explicit --resume for an unfinished campaign"
            )
        output.mkdir(parents=True)
        publish(output / "campaign.json", campaign.wire())
        publish(output / "campaign-inputs.json", input_identity)
    spent = sum(
        int(json.loads(path.read_bytes())["reserved_ms"])
        for path in output.glob("admission-*.json")
    )
    deadline = time.monotonic() + (campaign.budget_ms - spent) / 1000
    runs = []
    failures = []
    for index, comparison in enumerate(campaign.comparisons):
        session = output / ("session-" + str(index + 1))
        allowance = (campaign.startup_ms + comparison.budget_ms) / 1000 + 15
        admission = output / ("admission-" + str(index + 1) + ".json")
        if admission.exists():
            run = output / ("comparison-" + str(index + 1))
            closed = (
                json.loads((session / "closed.json").read_bytes())
                if (session / "closed.json").exists()
                else {}
            )
            completed = (
                json.loads((run / "result.json").read_bytes())
                if (run / "result.json").exists()
                else {}
            )
            if (
                completed.get("state") != "complete"
                or closed.get("returncode") != 0
                or closed.get("world_recovery_pending") is not False
                or closed.get("shader_recovery_pending") is not False
                or closed.get("profile_artifact_restored") is not True
            ):
                raise ValueError(
                    "prior admitted session is incomplete or not proven closed; no replay or automatic replacement"
                )
            receipt = json.loads((run / "receipt.json").read_bytes())
            if (
                receipt.get("sha256")
                != hashlib.sha256((run / "result.json").read_bytes()).hexdigest()
            ):
                raise ValueError("resumed comparison receipt differs")
            runs.append(run / "result.json")
            continue
        if control is not None and control.exists():
            request = json.loads(control.read_bytes())
            if (
                set(request) != {"action", "after_sessions"}
                or request["action"] != "pause"
                or type(request["after_sessions"]) is not int
                or request["after_sessions"] < 0
            ):
                raise ValueError(
                    "campaign control requires explicit pause and completed-session boundary"
                )
            if len(runs) >= request["after_sessions"]:
                paused: dict[str, object] = {
                    "schema": "shaderlod-campaign-pause-v1",
                    "state": "paused",
                    "completed_sessions": len(runs),
                    "reserved_ms": spent,
                    "remaining_plan_unchanged": True,
                }
                checkpoint = output / ("paused-" + str(len(runs)) + ".json")
                if not checkpoint.exists():
                    publish(checkpoint, paused)
                return paused
        if time.monotonic() + allowance > deadline:
            failures.append(
                {
                    "session": index + 1,
                    "failure": "remaining campaign budget cannot admit complete planned session",
                }
            )
            break
        publish(
            admission,
            {
                "schema": "shaderlod-campaign-admission-v1",
                "session": index + 1,
                "reserved_ms": int(allowance * 1000),
                "started_unix_ns": time.time_ns(),
            },
        )
        spent += int(allowance * 1000)
        argv = [
            sys.executable,
            "-m",
            "shaderlod_host",
            "session-open",
            "--launch",
            str(launch.resolve()),
            "--profile",
            str(profile.resolve()),
            "--display",
            str(display.resolve()),
            "--ownership-root",
            str(ownership.resolve()),
            "--session",
            str(session.resolve()),
            "--timeout",
            str(int(allowance)),
            "--world",
            world,
            "--telemetry",
            "--ancestor-pid",
            str(os.getpid()),
            "--ancestor-birth",
            birth(os.getpid()),
        ]
        with (output / ("launcher-" + str(index + 1) + ".log")).open("xb") as log:
            owner = subprocess.Popen(
                argv,
                stdin=subprocess.DEVNULL,
                stdout=log,
                stderr=subprocess.STDOUT,
                env=worker_environment(),
            )
            try:
                ready_deadline = time.monotonic() + campaign.startup_ms / 1000
                while not (session / "session.json").exists():
                    if owner.poll() is not None or time.monotonic() >= ready_deadline:
                        raise ValueError(
                            "session startup failed or exhausted its fixed allowance"
                        )
                    time.sleep(0.05)
                wait_ready(session, max(0.1, ready_deadline - time.monotonic()))
                run = output / ("comparison-" + str(index + 1))
                result = execute_comparison(
                    comparison, session, run, policy=campaign.policy.wire()
                )
                runs.append(run / "result.json")
                if result["state"] != "complete":
                    raise ValueError(
                        "planned comparison incomplete; no automatic retry"
                    )
            except (OSError, ValueError, RuntimeError) as error:
                failures.append({"session": index + 1, "failure": str(error)})
            finally:
                if owner.poll() is None:
                    try:
                        session_command(
                            session,
                            "close",
                            0,
                            min(15, max(0.1, deadline - time.monotonic())),
                        )
                    except (OSError, ValueError, RuntimeError) as error:
                        failures.append(
                            {"session": index + 1, "close_failure": str(error)}
                        )
                        owner.terminate()
                try:
                    owner.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    owner.kill()
                    owner.wait(timeout=3)
                    failures.append(
                        {
                            "session": index + 1,
                            "close_failure": "supervisor forced down; inspect recovery journals",
                        }
                    )
            if failures:
                break
    assessment = assess(campaign.policy, runs) if runs else None
    result = {
        "schema": "shaderlod-campaign-result-v1",
        "state": "complete"
        if len(runs) == len(campaign.comparisons) and not failures
        else "incomplete",
        "runs": [str(path.relative_to(output)) for path in runs],
        "failures": failures,
        "assessment": assessment,
        "quality": "required separately; no automatic acceptance",
    }
    publish(output / "result.json", result)
    return result


def freeze_windows_runtime(legacy: Path, output: Path, root: Path) -> dict[str, object]:
    from shaderlod_host.storage import publish_bytes, replace_bytes

    if os.name != "nt" or output.exists() or output.resolve().is_relative_to(root):
        raise ValueError("fresh external native Windows runtime destination required")
    manifest_path = root / "build/moddev/windows-launch.json"
    manifest = json.loads(manifest_path.read_bytes())
    legacy = legacy.resolve(strict=True)
    argv = list(manifest["argv"])
    old_classpath = (root / "build/moddev/developmentLegacyClasspath.txt").read_text()
    sources = {Path(item) for item in argv[argv.index("-cp") + 1].split(os.pathsep)}
    sources.update(Path(item) for item in old_classpath.splitlines() if item)
    copied = {}
    total = sum(
        p.stat().st_size for p in sources if p.is_file() and p.is_relative_to(legacy)
    )
    output.parent.mkdir(parents=True, exist_ok=True)
    if shutil.disk_usage(output.parent).free < total + 1073741824:
        raise ValueError("insufficient capacity for runtime snapshot and reserve")
    output.mkdir()
    for path in sorted(sources):
        if path.is_relative_to(legacy):
            target = output / path.relative_to(legacy)
            payload = path.read_bytes()
            publish_bytes(target, payload)
            copied[str(target)] = hashlib.sha256(payload).hexdigest()

    def relocated(text: str) -> str:
        return text.replace(str(legacy), str(output)).replace(
            legacy.as_posix(), output.as_posix()
        )

    argv[argv.index("-cp") + 1] = relocated(argv[argv.index("-cp") + 1])
    vm = next(Path(item[1:]) for item in argv if item.startswith("@"))
    base_vm = vm.read_text().split("# User JVM Arguments")[0]
    logging = legacy / "build/moddev/clientLodOnLog4j2.xml"
    publish_bytes(output / "logging.xml", logging.read_bytes())
    new_vm = output / "vm-args.txt"
    entries = [
        base_vm,
        "-Xmx6G",
        "-Dlog4j2.configurationFile=" + (output / "logging.xml").as_posix(),
        "-Djava.net.preferIPv6Addresses=system",
        "-DignoreList=mixinextras-neoforge-0.5.3.jar,client-extra,neoforge-",
        "-DlegacyClassPath.file="
        + (root / "build/moddev/developmentLegacyClasspath.txt").as_posix(),
    ]
    publish_bytes(new_vm, ("\n".join(entries) + "\n").encode())
    argv[argv.index("@" + str(vm))] = "@" + str(new_vm)
    manifest["argv"] = argv
    manifest["runtime_snapshot"] = str(output)
    serialized = json.dumps(manifest, sort_keys=True).encode()
    if (
        str(legacy).encode() in serialized
        or str(legacy).encode() in new_vm.read_bytes()
    ):
        raise ValueError(
            "source checkout dependency remains; snapshot preserved without changing launch"
        )
    publish_bytes(output / "previous-launch.json", manifest_path.read_bytes())
    publish_bytes(output / "previous-legacy-classpath.txt", old_classpath.encode())
    replace_bytes(
        root / "build/moddev/developmentLegacyClasspath.txt",
        relocated(old_classpath).encode(),
    )
    replace_bytes(manifest_path, serialized)
    record: dict[str, object] = {
        "schema": "shaderlod-windows-runtime-snapshot-v1",
        "files": copied,
        "copied_bytes": total,
        "runtime": str(output),
        "launch_sha256": hashlib.sha256(serialized).hexdigest(),
        "shared_dependencies": "Existing user-owned toolchain and Gradle artifact cache outside the original source checkout remain referenced",
    }
    publish(output / "manifest.json", record)
    return record


def execute_installation(
    plan: object,
    launch: Path,
    profile: Path,
    display: Path,
    ownership: Path,
    output: Path,
    world: str,
) -> dict[str, object]:
    from shaderlod_host.benchmark import save_live_capture, session_command, wait_ready
    from shaderlod_host.comparison import (
        ComparisonPlan,
        installation_plan,
        render_comparison,
        configuration,
        conditions_match,
        workload_failure,
    )
    from shaderlod_host.storage import publish_bytes

    if (
        not isinstance(plan, ComparisonPlan)
        or len(plan.cases) != 1
        or len(plan.arms) != 2
        or any(arm.modules or arm.delay_ms for arm in plan.arms)
        or plan.instrument != "frames"
        or plan.quality_cadence_ms
        or output.exists()
    ):
        raise ValueError(
            "installation needs one case, two empty arms, frame-only capture and fresh output"
        )
    installation_plan(plan)
    started = time.monotonic()
    output.mkdir(parents=True)
    publish(
        output / "plan.json",
        {
            "definition": plan.wire(),
            "mode": "native / installed-Off in fresh paired processes",
        },
    )
    case = plan.cases[0]
    payload = (profile / "shaderpacks" / case.pack).read_bytes()
    if hashlib.sha256(payload).hexdigest() != case.sha256:
        raise ValueError("installation original archive identity disagreement")
    publish_bytes(output / (case.sha256 + ".zip"), payload)
    deadline = time.monotonic() + plan.budget_ms / 1000
    observations: list[dict[str, object]] = []
    failure = None
    reference_config = None
    for index, (block, _, arm) in enumerate(plan.schedule()):
        absent = arm.identity == plan.arms[0].identity
        session = output / ("session-" + str(index + 1))
        remaining = deadline - time.monotonic()
        if remaining < (plan.window_ms + plan.warmup_ms) / 1000 + 20:
            failure = "installation budget cannot admit another complete process"
            break
        allowance = min(180, int(remaining))
        argv = [
            sys.executable,
            "-m",
            "shaderlod_host",
            "session-open",
            "--launch",
            str(launch.resolve()),
            "--profile",
            str(profile.resolve()),
            "--display",
            str(display.resolve()),
            "--ownership-root",
            str(ownership.resolve()),
            "--session",
            str(session.resolve()),
            "--timeout",
            str(allowance),
            "--world",
            world,
            "--ancestor-pid",
            str(os.getpid()),
            "--ancestor-birth",
            birth(os.getpid()),
        ]
        if absent:
            argv.append("--without-shaderlod")
        with (output / ("launcher-" + str(index + 1) + ".log")).open("xb") as log:
            owner = subprocess.Popen(
                argv,
                stdin=subprocess.DEVNULL,
                stdout=log,
                stderr=subprocess.STDOUT,
                env=worker_environment(),
            )
            try:
                ready_deadline = time.monotonic() + min(
                    120, allowance - (plan.window_ms + plan.warmup_ms) / 1000 - 15
                )
                while not (session / "session.json").exists():
                    if owner.poll() is not None or time.monotonic() >= ready_deadline:
                        raise ValueError("installation session failed during startup")
                    time.sleep(0.05)
                wait_ready(session, max(0.1, ready_deadline - time.monotonic()))
                session_command(
                    session,
                    "prepare",
                    0,
                    15,
                    {
                        "day_time": case.day_time,
                        "weather": case.weather,
                        "pose": list(case.start),
                    },
                )
                conditions_deadline = min(deadline - 15, time.monotonic() + 10)
                status = session_command(session, "status", 0, 10)
                while not conditions_match(case, status):
                    if time.monotonic() >= conditions_deadline:
                        raise ValueError(
                            "installation weather/time readiness exhausted"
                        )
                    time.sleep(0.05)
                    status = session_command(session, "status", 0, 10)
                time.sleep(plan.warmup_ms / 1000)
                status = session_command(session, "status", 0, 10)
                mods = status.get("runtime_mods")
                activation = status.get("activation")
                if (
                    not isinstance(mods, dict)
                    or (mods.get("shaderlod") == "absent") != absent
                    or not isinstance(activation, dict)
                    or activation.get("archiveSha256") != case.sha256
                    or status.get("surface") != list(case.surface)
                    or not conditions_match(case, status)
                ):
                    raise ValueError(
                        "actual mod presence, native graph, surface or conditions differ from installation plan"
                    )
                config = configuration(status)
                if reference_config is not None and config != reference_config:
                    raise ValueError("native and installed-Off configurations differ")
                reference_config = config
                window_started = time.monotonic() - started
                observed = session_command(
                    session,
                    "capture",
                    plan.window_ms,
                    min(310, max(0.1, deadline - time.monotonic() - 15)),
                    {"from": list(case.start), "to": list(case.end), "delay_ms": 0},
                )
                capture = output / ("capture-" + str(index + 1))
                summary = save_live_capture(observed, capture)
                if (
                    summary["valid"] is not True
                    or workload_failure(case, observed, plan.window_ms) is not None
                    or configuration(observed) != config
                ):
                    raise ValueError("installation capture invalid")
                observations.append(
                    {
                        "block": block,
                        "mode": "native" if absent else "installed-Off",
                        "summary": summary,
                        "selection": status,
                        "capture": capture.name,
                        "arm": "native" if absent else "installed-Off",
                        "case": case.identity,
                        "attempt": capture.name,
                        "quality_only": False,
                        "window_started_seconds": window_started,
                    }
                )
            except (OSError, ValueError, RuntimeError) as error:
                failure = str(error)
            finally:
                if owner.poll() is None:
                    try:
                        session_command(
                            session,
                            "close",
                            0,
                            min(15, max(0.1, deadline - time.monotonic())),
                        )
                    except (OSError, ValueError, RuntimeError) as error:
                        failure = (failure or "") + "; close: " + str(error)
                        owner.terminate()
                try:
                    owner.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    owner.kill()
                    owner.wait(timeout=3)
                    failure = (
                        failure or ""
                    ) + "; supervisor forced down; recovery required"
            if failure is not None:
                break
    result: dict[str, object] = {
        "schema": "shaderlod-installation-result-v1",
        "state": "complete"
        if failure is None and len(observations) == len(plan.schedule())
        else "incomplete",
        "observations": observations,
        "failure": failure,
        "scope": "Main mod registration/mixins installed-Off versus measurement-only development mod with common helper classes. Declared native operating mode; capped throughput cannot establish rendering headroom. No automatic retention.",
    }
    publish_bytes(
        output / "report.html",
        render_comparison(
            result
            | {
                "qualification": "bounded installation control",
                "retention": "no automatic admission",
            }
        ).encode(),
    )
    publish(output / "result.json", result)
    publish(
        output / "receipt.json",
        {
            "schema": "shaderlod-installation-receipt-v1",
            "sha256": hashlib.sha256((output / "result.json").read_bytes()).hexdigest(),
        },
    )
    return result

package com.pp.shaderlod.dev;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.pp.shaderlod.storage.AtomicFiles;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import net.minecraft.client.Minecraft;
import net.neoforged.neoforge.client.event.ClientTickEvent;

final class BenchmarkControl {
  private final Path directory;
  private final BenchmarkWorld world;
  private java.util.concurrent.CompletableFuture<java.util.Map<String, Object>> worldAction;
  private boolean closing;
  private boolean idleClosing;
  private long lastActivity = System.nanoTime();
  private Boolean originalFullscreen;
  private final Gson gson = new Gson();
  private long sequence;
  private long started;
  private long duration;
  private int captureWidth;
  private int captureHeight;
  private boolean contextLost;
  private boolean durableChunks = true;
  private String captureDimension;
  private long activeWorldFrames;
  private boolean observingFrame;
  private boolean worldRendered;
  private java.util.List<String> selectedModules = java.util.List.of();
  private FrameCapture capture;
  private CaptureSpool spool;
  private com.pp.shaderlod.dev.measurement.StageProfiler stages;
  private long callbacks;
  private int spooled;
  private long spooledAt;
  private String fault;
  private long reconciledFailure = -1;
  private final com.pp.shaderlod.integration.IrisSelection backend =
      new com.pp.shaderlod.integration.IrisSelection();
  private final com.pp.shaderlod.integration.ShaderController modules =
      new com.pp.shaderlod.integration.ShaderController();
  private com.pp.shaderlod.engine.SelectionTransaction selection;
  private boolean moduleSelection;
  private boolean pendingSelect;
  private FunctionalProbe functional;
  private long selectionStarted;
  private CameraRoute route;
  private java.util.List<Double> originalPose;
  private java.util.List<Double> scenarioOriginalPose;
  private int delayMillis;
  private long delayExecuted;
  private long checkpointTime;
  private long routeTicks;
  private long viewCheckpointTime;
  private long qualityCadence;
  private CaptureCadence qualityClock;
  private java.util.List<Double> latestCamera = java.util.List.of();
  private long cameraObserved;
  private QualityCapture quality;
  private final java.util.List<java.util.Map<String, Object>> viewCheckpoints =
      new java.util.ArrayList<>();
  private final java.util.List<java.util.Map<String, Object>> checkpoints =
      new java.util.ArrayList<>();

  BenchmarkControl(Path directory) {
    this.directory = directory;
    world = new BenchmarkWorld(directory);
  }

  void frame(long timestamp, long generation) {
    if (capture != null) {
      contextLost |= observingFrame && !worldRendered;
      observingFrame = true;
      worldRendered = false;
      var client = Minecraft.getInstance();
      contextLost |=
          client.level == null
              || client.player == null
              || client.screen != null
              || client.getOverlay() != null
              || !client.isWindowActive()
              || client.getMainRenderTarget().width != captureWidth
              || client.getMainRenderTarget().height != captureHeight
              || !String.valueOf(net.irisshaders.iris.Iris.getCurrentDimension())
                  .equals(captureDimension);
      if (route != null && timestamp - checkpointTime >= 250000000) {
        checkpoints.add(
            java.util.Map.of(
                "elapsed_ns",
                timestamp - started,
                "pose",
                currentPose(),
                "client_ticks",
                routeTicks));
        checkpointTime = timestamp;
      }
      capture.observe(timestamp, generation);
      if (durableChunks && timestamp - spooledAt >= 1000000000) {
        spool.offer(capture.since(spooled));
        spooled = capture.count();
        spooledAt = timestamp;
      }
      if (stages != null) {
        stages.begin(generation, ++callbacks);
      }
      if (delayMillis != 0) {
        long delayStart = System.nanoTime();
        long delayEnd = delayStart + delayMillis * 1000000L;
        long remaining;
        while ((remaining = delayEnd - System.nanoTime()) > 0) {
          java.util.concurrent.locks.LockSupport.parkNanos(remaining);
        }
        delayExecuted += System.nanoTime() - delayStart;
      }
    }
  }

  void stage(net.neoforged.neoforge.client.event.RenderLevelStageEvent event) {
    boolean shadow = net.irisshaders.iris.api.v0.IrisApi.getInstance().isRenderingShadowPass();
    if (capture != null
        && !shadow
        && event
            .getStage()
            .equals(net.neoforged.neoforge.client.event.RenderLevelStageEvent.Stage.AFTER_LEVEL)
        && net.irisshaders.iris.api.v0.IrisApi.getInstance().isShaderPackInUse()
        && !net.irisshaders.iris.Iris.isFallback()) {
      activeWorldFrames++;
      worldRendered = true;
    }
    if (capture != null
        && route != null
        && !shadow
        && event
            .getStage()
            .equals(net.neoforged.neoforge.client.event.RenderLevelStageEvent.Stage.AFTER_SKY)) {
      var camera = event.getCamera();
      var point = camera.getPosition();
      cameraObserved = System.nanoTime();
      latestCamera =
          java.util.List.of(
              point.x, point.y, point.z, (double) camera.getYRot(), (double) camera.getXRot());
      if (cameraObserved - viewCheckpointTime >= 250000000) {
        viewCheckpointTime = System.nanoTime();
        viewCheckpoints.add(
            java.util.Map.of(
                "elapsed_ns",
                viewCheckpointTime - started,
                "client_ticks",
                routeTicks,
                "player_pose",
                currentPose(),
                "camera_pose",
                java.util.List.of(
                    point.x,
                    point.y,
                    point.z,
                    (double) camera.getYRot(),
                    (double) camera.getXRot()),
                "eye_height",
                Minecraft.getInstance().player.getEyeHeight(),
                "first_person",
                Minecraft.getInstance().options.getCameraType().isFirstPerson()));
      }
    }
    if (stages != null) {
      stages.boundary((shadow ? "shadow/" : "main/") + event.getStage());
    }
  }

  void endFrame() {
    if (stages != null) {
      stages.end();
    }
    if (capture != null && qualityClock != null && qualityClock.due(System.nanoTime())) {
      long readbackStart = System.nanoTime();
      var image =
          net.minecraft.client.Screenshot.takeScreenshot(
              Minecraft.getInstance().getMainRenderTarget());
      long readbackEnd = System.nanoTime();
      quality.offer(
          "motion-" + sequence + "-" + readbackStart + ".png",
          image,
          java.util.Map.of(
              "elapsed_ns",
              readbackStart - started,
              "readback_ns",
              readbackEnd - readbackStart,
              "client_ticks",
              routeTicks,
              "pose",
              currentPose(),
              "camera_pose",
              latestCamera,
              "camera_observed_ns",
              cameraObserved,
              "frame_start_ns",
              capture.latestTimestamp(),
              "first_person",
              Minecraft.getInstance().options.getCameraType().isFirstPerson()));
    }
  }

  void tick(ClientTickEvent.Post event) {
    try {
      if (Minecraft.getInstance().level == null) {
        lastActivity = System.nanoTime();
      }
      if (fault != null) {
        Path recovery = directory.resolve("command-" + (sequence + 1) + ".json");
        if (!Files.isRegularFile(recovery) || Files.size(recovery) > 4096) {
          return;
        }
        var close =
            ControlRequest.decode(
                gson.fromJson(Files.readString(recovery), JsonObject.class), sequence + 1);
        if (!close.action().equals("close") && !close.action().equals("recover")) {
          return;
        }
        reconciledFailure = sequence;
        if (originalPose != null) {
          position(originalPose);
        }
        capture = null;
        functional = null;
        if (quality != null) {
          quality.finish();
          quality = null;
        }
        if (spool != null) {
          spool.finish();
        }
        if (stages != null) {
          stages.finish();
          stages = null;
        }
        pendingSelect = false;
        worldAction = null;
        fault = null;
      }
      modules.tick();
      if (functional != null) {
        functional.tick(event);
        if (functional.done()) {
          functional = null;
          publish(state());
        }
        return;
      }
      if (worldAction != null) {
        if (!worldAction.isDone()) {
          return;
        }
        var change = worldAction.join();
        worldAction = null;
        var record = state();
        record.put("world", change);
        if (idleClosing) {
          AtomicFiles.publish(
              directory.resolve("idle-close.json"),
              gson.toJson(record).getBytes(StandardCharsets.UTF_8));
        } else {
          publish(record);
        }
        lastActivity = System.nanoTime();
        if (closing) {
          if (originalFullscreen != null
              && Minecraft.getInstance().getWindow().isFullscreen() != originalFullscreen) {
            Minecraft.getInstance().getWindow().toggleFullScreen();
          }
          Minecraft.getInstance().stop();
        }
        return;
      }
      if (pendingSelect) {
        if (System.nanoTime() - selectionStarted > 60000000000L) {
          throw new IOException("Selection did not render before deadline");
        }
        if (!backend.hasSubmittedFrame() || !Boolean.TRUE.equals(state().get("ready"))) {
          return;
        }
        if (moduleSelection) {
          if (!modules.status().equals("ACTIVE")) {
            return;
          }
        } else {
          selection.confirmRendered();
        }
        pendingSelect = false;
        publish(state());
        return;
      }
      if (capture != null) {
        if (route != null) {
          routeTicks++;
          var pose = route.at(routeTicks / (duration / 50000000.0));
          var client = Minecraft.getInstance();
          if (client.level == null
              || !client.level.hasChunk(
                  ((int) Math.floor(pose.get(0))) >> 4, ((int) Math.floor(pose.get(2))) >> 4)) {
            throw new IOException("Route left admitted loaded region");
          }
          position(pose, false);
        }
        if (System.nanoTime() - started >= duration) {
          if (durableChunks) {
            spool.offer(capture.since(spooled));
          }
          var result = capture.finish();
          capture = null;
          var spoolStatus = spool.finish();
          var record = state();
          record.put("capture", result);
          record.put("spool", spoolStatus);
          record.put("durable_chunks", durableChunks);
          if (stages != null) {
            record.put("stage_profile", stages.finish());
            stages = null;
          }
          record.put("checkpoints", java.util.List.copyOf(checkpoints));
          record.put("view_checkpoints", java.util.List.copyOf(viewCheckpoints));
          record.put("progression_clock", "client-simulation-ticks-20hz");
          record.put("elapsed_client_ticks", routeTicks);
          record.put("expected_client_ticks", duration / 50000000.0);
          record.put("delay_ms", delayMillis);
          record.put("context_lost", contextLost);
          record.put("active_world_frames", activeWorldFrames);
          record.put("executed_delay_ns", delayExecuted);
          record.put("quality_cadence_ns", qualityCadence);
          record.put("quality_skipped_slots", qualityClock == null ? 0 : qualityClock.skipped());
          if (quality != null) {
            var qualityResult = quality.finish();
            record.put("quality_frames", qualityResult.get("frames"));
            record.put("quality_status", qualityResult);
            quality = null;
          }
          if (originalPose != null) {
            position(originalPose);
          }
          route = null;
          originalPose = null;
          delayMillis = 0;
          record.put("elapsed_ns", System.nanoTime() - started);
          record.put(
              "valid",
              !result.overflow()
                  && !contextLost
                  && worldRendered
                  && activeWorldFrames >= result.frames().size()
                  && !result.generationChanged()
                  && !result.frames().isEmpty()
                  && Boolean.TRUE.equals(spoolStatus.get("complete")));
          publish(record);
        }
        return;
      }
      if (!closing
          && Minecraft.getInstance().level != null
          && System.nanoTime() - lastActivity > 120000000000L) {
        restore();
        closing = true;
        idleClosing = true;
        restorePose();
        worldAction = world.set(true);
        return;
      }
      Path command = directory.resolve("command-" + (sequence + 1) + ".json");
      if (!Files.isRegularFile(command)) {
        return;
      }
      if (Files.size(command) > 4096) {
        throw new IOException("Command exceeds size limit");
      }
      var request =
          ControlRequest.decode(
              gson.fromJson(Files.readString(command), JsonObject.class), sequence + 1);
      sequence = request.sequence();
      lastActivity = System.nanoTime();
      String action = request.action();
      if (action.equals("status")) {
        publish(state());
      } else if (action.equals("validate")) {
        restore();
        if (!Boolean.TRUE.equals(state().get("ready"))
            || !net.irisshaders.iris.Iris.getCurrentPackName()
                .equals("ComplementaryReimagined_r5.9.3.zip")) {
          throw new IOException("Validation requires a rendered original primary pack selection");
        }
        for (String name :
            java.util.List.of(
                "shaderlod-functional.json",
                "shaderlod-functional.png",
                "shaderlod-functional-identity.png")) {
          if (Files.exists(net.neoforged.fml.loading.FMLPaths.GAMEDIR.get().resolve(name))) {
            throw new IOException("Prior functional evidence must be preserved before validation");
          }
        }
        functional = new FunctionalProbe(false);
      } else if (action.equals("prepare")) {
        var client = Minecraft.getInstance();
        if (originalFullscreen == null) {
          originalFullscreen = client.getWindow().isFullscreen();
        }
        if (!client.getWindow().isFullscreen()) {
          client.getWindow().toggleFullScreen();
        }
        org.lwjgl.glfw.GLFW.glfwFocusWindow(client.getWindow().getWindow());
        client.setScreen(null);
        if (request.payload().isEmpty()) {
          worldAction = world.set(false);
        } else {
          String weather = request.payload().get("weather").getAsString();
          worldAction =
              world.set(
                  false,
                  request.payload().get("day_time").getAsInt(),
                  !weather.equals("clear"),
                  weather.equals("thunder"));
        }
        if (request.payload().has("pose")) {
          var pose = vector(request.payload().getAsJsonArray("pose"));
          new CameraRoute(pose, pose);
          if (scenarioOriginalPose == null) {
            scenarioOriginalPose = currentPose();
          }
          if (distance(scenarioOriginalPose, pose) > 4096) {
            throw new IOException("Scenario exceeds 64 blocks from owned pose preimage");
          }
          position(pose);
        }
      } else if (action.equals("screenshot")) {
        var record = state();
        record.putAll(image("quality-" + sequence + ".png"));
        publish(record);
      } else if (action.equals("recover")) {
        restore();
        restorePose();
        closing = false;
        worldAction = world.set(true);
      } else if (action.equals("restore")) {
        restore();
        restorePose();
        publish(state());
      } else if (action.equals("select")) {
        select(request.payload());
      } else if (action.equals("close")) {
        restore();
        restorePose();
        closing = true;
        worldAction = world.set(true);
      } else if (action.equals("capture")) {
        long millis = request.durationMillis();
        if (millis < 100 || millis > 300000 || !Boolean.TRUE.equals(state().get("ready"))) {
          throw new IOException("Ready world and bounded 100–300000 ms capture required");
        }
        checkpoints.clear();
        viewCheckpoints.clear();
        viewCheckpointTime = 0;
        routeTicks = 0;
        route = null;
        originalPose = null;
        delayMillis = 0;
        delayExecuted = 0;
        durableChunks =
            !request.payload().has("durable_chunks")
                || request.payload().get("durable_chunks").getAsBoolean();
        quality = null;
        qualityClock = null;
        latestCamera = java.util.List.of();
        qualityCadence =
            request.payload().has("quality_cadence_ms")
                ? request.payload().get("quality_cadence_ms").getAsLong() * 1000000
                : 0;
        if (qualityCadence != 0
            && (qualityCadence < 100000000 || qualityCadence > 1000000000 || millis > 10000)) {
          throw new IOException(
              "Quality sequence requires 100–1000 ms cadence and at most 10 seconds");
        }
        if (!request.payload().isEmpty()) {
          route =
              new CameraRoute(
                  vector(request.payload().getAsJsonArray("from")),
                  vector(request.payload().getAsJsonArray("to")));
          originalPose = currentPose();
          var anchor = scenarioOriginalPose == null ? originalPose : scenarioOriginalPose;
          if (distance(anchor, route.from()) > 4096 || distance(anchor, route.to()) > 4096) {
            throw new IOException("Route start exceeds 64 blocks from current position");
          }
          delayMillis = request.payload().get("delay_ms").getAsInt();
          if (delayMillis < 0
              || delayMillis > 100
              || !request.payload().get("delay_ms").toString().matches("[0-9]+")) {
            throw new IOException("Invalid test control delay");
          }
          position(route.from());
        }
        duration = millis * 1000000;
        contextLost = false;
        activeWorldFrames = 0;
        observingFrame = false;
        worldRendered = false;
        captureWidth = Minecraft.getInstance().getMainRenderTarget().width;
        captureHeight = Minecraft.getInstance().getMainRenderTarget().height;
        captureDimension = String.valueOf(net.irisshaders.iris.Iris.getCurrentDimension());
        checkpointTime = 0;
        AtomicFiles.publish(
            directory.resolve("capture-" + sequence + "-started.json"),
            gson.toJson(state()).getBytes(StandardCharsets.UTF_8));
        stages =
            request.payload().has("diagnostic")
                    && request.payload().get("diagnostic").getAsBoolean()
                ? new com.pp.shaderlod.dev.measurement.StageProfiler()
                : null;
        callbacks = 0;
        capture = new FrameCapture(200000);
        if (qualityCadence > 0) {
          quality = new QualityCapture(directory);
        }
        spool = new CaptureSpool(directory, sequence);
        spooled = 0;
        started = System.nanoTime();
        qualityClock = qualityCadence > 0 ? new CaptureCadence(started, qualityCadence) : null;
        spooledAt = started;
      } else {
        throw new IOException("Unsupported command");
      }
    } catch (IOException
        | IllegalArgumentException
        | IllegalStateException
        | com.google.gson.JsonParseException
        | java.util.concurrent.CompletionException failure) {
      fault = failure.getMessage();
      var record = state();
      record.put("failure", fault);
      try {
        AtomicFiles.publish(
            directory.resolve("failure-" + sequence + ".json"),
            gson.toJson(record).getBytes(StandardCharsets.UTF_8));
        if (!Files.exists(directory.resolve("failure.json"))) {
          AtomicFiles.publish(
              directory.resolve("failure.json"),
              gson.toJson(record).getBytes(StandardCharsets.UTF_8));
        }
      } catch (IOException publicationFailure) {
        net.irisshaders.iris.Iris.logger.error(
            "Benchmark failure publication failed", publicationFailure);
      }
    }
  }

  private java.util.Map<String, Object> state() {
    var client = Minecraft.getInstance();
    var record = new LinkedHashMap<String, Object>();
    record.put("schema", "shaderlod-control-result-v1");
    record.put("sequence", sequence);
    record.put("recovered_failure_sequence", reconciledFailure);
    record.put("pack", net.irisshaders.iris.Iris.getCurrentPackName());
    record.put("fallback", net.irisshaders.iris.Iris.isFallback());
    record.put("world_loaded", client.level != null && client.player != null);
    record.put(
        "ready",
        client.level != null
            && client.player != null
            && client.screen == null
            && client.getOverlay() == null
            && client.isWindowActive()
            && client.levelRenderer.countRenderedSections() > 0
            && !net.irisshaders.iris.Iris.isFallback());
    record.put(
        "surface",
        java.util.List.of(client.getMainRenderTarget().width, client.getMainRenderTarget().height));
    record.put(
        "generation",
        net.irisshaders.iris.Iris.getPipelineManager().getVersionCounterForSodiumShaderReload());
    record.put("world_day_time", client.level == null ? -1 : client.level.getDayTime());
    record.put("rain", client.level == null ? -1 : client.level.getRainLevel(1));
    record.put("thunder", client.level == null ? -1 : client.level.getThunderLevel(1));
    record.put("focused", client.isWindowActive());
    var monitor = org.lwjgl.glfw.GLFW.glfwGetVideoMode(org.lwjgl.glfw.GLFW.glfwGetPrimaryMonitor());
    record.put(
        "monitor",
        monitor == null
            ? java.util.List.of()
            : java.util.List.of(monitor.width(), monitor.height(), monitor.refreshRate()));
    record.put("renderer", com.pp.shaderlod.dev.measurement.RenderEnvironment.current());
    record.put("runtime", com.pp.shaderlod.dev.config.DevelopmentSettings.runtimeIdentity());
    var runtimeMods = new java.util.TreeMap<String, String>();
    for (String id :
        java.util.List.of("neoforge", "iris", "sodium", "distanthorizons", "shaderlod")) {
      runtimeMods.put(
          id,
          net.neoforged.fml.ModList.get()
              .getModContainerById(id)
              .map(mod -> mod.getModInfo().getVersion().toString())
              .orElse("absent"));
    }
    record.put("runtime_mods", runtimeMods);
    record.put("minecraft", net.minecraft.SharedConstants.getCurrentVersion().getName());
    var server = client.getSingleplayerServer();
    if (server != null) {
      record.put("world_seed", server.overworld().getSeed());
      record.put(
          "world_path",
          server
              .getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT)
              .toAbsolutePath()
              .normalize()
              .toString());
    }
    record.put("resource_packs", client.getResourcePackRepository().getSelectedIds());
    var runtime = Runtime.getRuntime();
    record.put(
        "jvm_heap",
        java.util.Map.of(
            "used_bytes",
            runtime.totalMemory() - runtime.freeMemory(),
            "committed_bytes",
            runtime.totalMemory(),
            "limit_bytes",
            runtime.maxMemory()));
    record.put("dimension", String.valueOf(net.irisshaders.iris.Iris.getCurrentDimension()));
    record.put("dh", com.pp.shaderlod.integration.DhObservation.current());
    record.put(
        "probe_invocations",
        java.util.Map.of(
            "identity-probe",
            IdentityProvider.invocations(),
            "identity-companion-probe",
            IdentityCompanionProvider.invocations()));
    record.put("selection", selection == null ? modules.status() : selection.state().toString());
    record.put("selected_modules", selectedModules);
    if (moduleSelection && modules.status().equals("ACTIVE")) {
      record.put("activation", modules.activation());
    } else if (selection != null
        && selection.state() == com.pp.shaderlod.engine.SelectionTransaction.State.ACTIVE) {
      record.put("activation", selection.activation());
    }
    record.put("loaded_main_class_sha256", classDigest(com.pp.shaderlod.storage.AtomicFiles.class));
    record.put("loaded_dev_class_sha256", classDigest(BenchmarkControl.class));
    record.put("options", com.pp.shaderlod.integration.IrisSelection.effectiveOptions());
    if (!record.containsKey("activation")
        && net.irisshaders.iris.api.v0.IrisApi.getInstance().isShaderPackInUse()) {
      try {
        record.put("activation", backend.observe());
      } catch (IOException unavailable) {
        record.put("activation_unavailable", unavailable.toString());
      }
    }
    record.put(
        "client_options",
        java.util.Map.of(
            "render_distance",
            client.options.renderDistance().get(),
            "simulation_distance",
            client.options.simulationDistance().get(),
            "max_fps",
            client.options.framerateLimit().get(),
            "vsync",
            client.options.enableVsync().get(),
            "fov",
            client.options.fov().get()));
    if (client.player != null) {
      record.put(
          "pose",
          java.util.List.of(
              client.player.getX(),
              client.player.getY(),
              client.player.getZ(),
              client.player.getYRot(),
              client.player.getXRot()));
    }
    return record;
  }

  private java.util.Map<String, Object> image(String name) throws IOException {
    try (var image =
        net.minecraft.client.Screenshot.takeScreenshot(
            Minecraft.getInstance().getMainRenderTarget())) {
      byte[] png = image.asByteArray();
      AtomicFiles.publish(directory.resolve(name), png);
      var record = new LinkedHashMap<String, Object>();
      record.put("image", name);
      record.put("image_sha256", com.pp.shaderlod.storage.PackArchive.sha256(png));
      record.put(
          "image_has_variation",
          java.util.Arrays.stream(image.getPixelsRGBA()).distinct().limit(2).count() > 1);
      return record;
    }
  }

  private static String classDigest(Class<?> type) {
    try (var input = type.getResourceAsStream(type.getSimpleName() + ".class")) {
      if (input == null) {
        return "unavailable";
      }
      return com.pp.shaderlod.storage.PackArchive.sha256(input.readAllBytes());
    } catch (IOException failure) {
      return "unavailable";
    }
  }

  private static java.util.List<Double> vector(com.google.gson.JsonArray array) {
    if (array == null || array.size() != 5) {
      throw new IllegalArgumentException("Five numeric pose values required");
    }
    var values = new java.util.ArrayList<Double>();
    for (var element : array) {
      if (!element.isJsonPrimitive() || !element.getAsJsonPrimitive().isNumber()) {
        throw new IllegalArgumentException("Numeric pose required");
      }
      values.add(element.getAsDouble());
    }
    return java.util.List.copyOf(values);
  }

  private static java.util.List<Double> currentPose() {
    var player = Minecraft.getInstance().player;
    if (player == null) {
      throw new IllegalStateException("Player unavailable");
    }
    return java.util.List.of(
        player.getX(),
        player.getY(),
        player.getZ(),
        (double) player.getYRot(),
        (double) player.getXRot());
  }

  private static double distance(java.util.List<Double> a, java.util.List<Double> b) {
    double sum = 0;
    for (int i = 0; i < 3; i++) {
      sum += Math.pow(a.get(i) - b.get(i), 2);
    }
    return sum;
  }

  private static void position(java.util.List<Double> pose) {
    position(pose, true);
  }

  private static void position(java.util.List<Double> pose, boolean snap) {
    var player = Minecraft.getInstance().player;
    if (player == null) {
      throw new IllegalStateException("Player unavailable");
    }
    player.setPos(pose.get(0), pose.get(1), pose.get(2));
    if (snap) {
      player.xo = pose.get(0);
      player.yo = pose.get(1);
      player.zo = pose.get(2);
    }
    player.setYRot(pose.get(3).floatValue());
    player.setXRot(pose.get(4).floatValue());
    if (snap) {
      player.yRotO = player.getYRot();
      player.xRotO = player.getXRot();
    }
  }

  private void restore() throws IOException {
    if (selection != null) {
      selection.off();
      selection = null;
    }
    modules.off();
    moduleSelection = false;
    selectedModules = java.util.List.of();
  }

  private void restorePose() {
    if (scenarioOriginalPose != null) {
      position(scenarioOriginalPose);
      scenarioOriginalPose = null;
    }
  }

  private void select(JsonObject payload) throws IOException {
    restore();
    if (!payload.get("pack").isJsonPrimitive()
        || !payload.get("pack").getAsJsonPrimitive().isString()
        || !payload.get("sha256").isJsonPrimitive()
        || !payload.get("modules").isJsonArray()) {
      throw new IOException("Invalid selection payload");
    }
    String pack = payload.get("pack").getAsString();
    String hash = payload.get("sha256").getAsString();
    var source = com.pp.shaderlod.integration.IrisSelection.archive(pack);
    var archive =
        com.pp.shaderlod.storage.PackArchive.read(
            source, com.pp.shaderlod.storage.PackArchive.Limits.defaults());
    if (!archive.identity().archiveSha256().equals(hash)) {
      throw new IOException("Requested archive digest differs");
    }
    var ids = new java.util.ArrayList<String>();
    for (var id : payload.getAsJsonArray("modules")) {
      if (!id.isJsonPrimitive() || !id.getAsJsonPrimitive().isString()) {
        throw new IOException("String module IDs required");
      }
      ids.add(id.getAsString());
    }
    if (ids.isEmpty()) {
      selection =
          com.pp.shaderlod.engine.SelectionTransaction.prepare(
              backend,
              new com.pp.shaderlod.domain.Selection(pack, true, java.util.Map.of(), ids),
              hash,
              java.util.Set.of("linked-archive:" + hash),
              net.irisshaders.iris.Iris.getPipelineManager()
                  .getVersionCounterForSodiumShaderReload());
      selection.apply();
    } else {
      moduleSelection = true;
      modules.apply(pack, ids);
      selectedModules = java.util.List.copyOf(ids);
    }
    selectionStarted = System.nanoTime();
    pendingSelect = true;
  }

  private void publish(java.util.Map<String, Object> record) throws IOException {
    AtomicFiles.publish(
        directory.resolve("result-" + sequence + ".json"),
        gson.toJson(record).getBytes(StandardCharsets.UTF_8));
    lastActivity = System.nanoTime();
  }
}

package com.pp.shaderlod.dev;

import com.google.gson.Gson;
import com.pp.shaderlod.storage.AtomicFiles;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import net.minecraft.client.Minecraft;
import net.minecraft.world.level.GameRules;

final class BenchmarkWorld {
  private Snapshot original;
  private byte[] journal;
  private int preimages;
  private final Path directory;
  private final Path journalPath;

  private record Snapshot(
      String savePath,
      long seed,
      String dimension,
      String playerId,
      java.util.List<Double> playerPose,
      long dayTime,
      boolean rain,
      boolean thunder,
      int clearTime,
      int rainTime,
      int thunderTime,
      boolean daylight,
      boolean weather,
      boolean mobs,
      int randomTicks) {}

  BenchmarkWorld(Path directory) {
    this.directory = directory;
    journalPath =
        net.neoforged.fml.loading.FMLPaths.GAMEDIR.get().resolve("shaderlod-benchmark-world.json");
  }

  CompletableFuture<Map<String, Object>> set(boolean restore) {
    return set(restore, 6000, false, false);
  }

  CompletableFuture<Map<String, Object>> set(
      boolean restore, int dayTime, boolean raining, boolean thundering) {
    var client = Minecraft.getInstance();
    var server = client.getSingleplayerServer();
    var dimension = client.level == null ? null : client.level.dimension();
    if (server == null || dimension == null || client.player == null) {
      return CompletableFuture.failedFuture(
          new IllegalStateException("Owned integrated world required"));
    }
    var clientPlayer = client.player;
    String playerId = clientPlayer.getUUID().toString();
    var playerPose =
        java.util.List.of(
            clientPlayer.getX(),
            clientPlayer.getY(),
            clientPlayer.getZ(),
            (double) clientPlayer.getYRot(),
            (double) clientPlayer.getXRot());
    return CompletableFuture.supplyAsync(
        () -> {
          var world = server.getLevel(dimension);
          if (world == null) {
            throw new IllegalStateException("Integrated dimension unavailable");
          }
          var rules = world.getGameRules();
          var data = (net.minecraft.world.level.storage.ServerLevelData) world.getLevelData();
          try {
            var save =
                server
                    .getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT)
                    .toAbsolutePath()
                    .normalize();
            if (original == null && Files.exists(journalPath)) {
              journal = Files.readAllBytes(journalPath);
              original =
                  new Gson().fromJson(new String(journal, StandardCharsets.UTF_8), Snapshot.class);
              if (original == null
                  || original.savePath() == null
                  || original.playerId() == null
                  || original.playerPose() == null
                  || original.playerPose().size() != 5
                  || !original.playerId().equals(playerId)
                  || !Path.of(original.savePath()).toAbsolutePath().normalize().equals(save)
                  || original.seed() != world.getSeed()
                  || !dimension.location().toString().equals(original.dimension())) {
                throw new IllegalStateException("World recovery identity differs");
              }
              if (!restore) {
                throw new IllegalStateException(
                    "Interrupted world journal requires restore before preparing another run");
              }
            }
            if (original == null && restore) {
              return Map.of("restored", true, "mutated", false);
            }
            if (original == null) {
              original =
                  new Snapshot(
                      save.toString(),
                      world.getSeed(),
                      dimension.location().toString(),
                      playerId,
                      playerPose,
                      world.getDayTime(),
                      world.isRaining(),
                      world.isThundering(),
                      data.getClearWeatherTime(),
                      data.getRainTime(),
                      data.getThunderTime(),
                      rules.getBoolean(GameRules.RULE_DAYLIGHT),
                      rules.getBoolean(GameRules.RULE_WEATHER_CYCLE),
                      rules.getBoolean(GameRules.RULE_DOMOBSPAWNING),
                      rules.getInt(GameRules.RULE_RANDOMTICKING));
              journal = new Gson().toJson(original).getBytes(StandardCharsets.UTF_8);
              AtomicFiles.publish(journalPath, journal);
              preimages++;
              AtomicFiles.publish(
                  directory.resolve("world-preimage-" + preimages + ".json"), journal);
            }
            if (restore) {
              var player =
                  server.getPlayerList().getPlayer(java.util.UUID.fromString(original.playerId()));
              if (player == null) {
                throw new IllegalStateException("Original benchmark player is unavailable");
              }
              var pose = original.playerPose();
              player.teleportTo(
                  world,
                  pose.get(0),
                  pose.get(1),
                  pose.get(2),
                  java.util.Set.of(),
                  pose.get(3).floatValue(),
                  pose.get(4).floatValue());
            }
            rules.getRule(GameRules.RULE_DAYLIGHT).set(restore && original.daylight(), server);
            rules.getRule(GameRules.RULE_WEATHER_CYCLE).set(restore && original.weather(), server);
            rules.getRule(GameRules.RULE_DOMOBSPAWNING).set(restore && original.mobs(), server);
            rules
                .getRule(GameRules.RULE_RANDOMTICKING)
                .set(restore ? original.randomTicks() : 0, server);
            world.setDayTime(restore ? original.dayTime() : dayTime);
            world.setWeatherParameters(
                restore ? original.clearTime() : (raining ? 0 : 6000),
                restore ? original.rainTime() : 6000,
                restore ? original.rain() : raining,
                restore ? original.thunder() : thundering);
            if (restore) {
              data.setThunderTime(original.thunderTime());
              AtomicFiles.removeIfUnchanged(journalPath, journal);
              original = null;
            }
            return Map.of(
                "restored",
                restore,
                "day_time",
                world.getDayTime(),
                "rain",
                world.isRaining(),
                "thunder",
                world.isThundering(),
                "dimension",
                dimension.location().toString());
          } catch (java.io.IOException failure) {
            throw new java.io.UncheckedIOException(failure);
          }
        },
        server);
  }
}

from dataclasses import dataclass
import hashlib
import json
import math
import socket
import time
from pathlib import Path
from typing import Iterable

from shaderlod_host.storage import publish, publish_bytes


class CommandIncomplete(RuntimeError):
    pass


def object_fields(value: object, fields: set[str], name: str) -> dict[str, object]:
    if not isinstance(value, dict) or set(value) != fields:
        raise ValueError(name + ": unexpected or missing fields")
    if not all(isinstance(key, str) for key in value):
        raise ValueError(name + ": non-string key")
    return value


def positive(value: object, name: str) -> int:
    if type(value) is not int or value < 1:
        raise ValueError(name + ": positive integer required")
    return value


def label(value: object, name: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 256:
        raise ValueError(name + ": bounded nonempty string required")
    return value


@dataclass(frozen=True)
class WorkflowPlan:
    scope: str
    workload: str
    arms: tuple[str, ...]
    blocks: int
    window_ms: int
    budget_ms: int
    instrument: str

    @classmethod
    def decode(cls, value: object) -> "WorkflowPlan":
        data = object_fields(
            value,
            {
                "schema",
                "scope",
                "workload",
                "arms",
                "blocks",
                "window_ms",
                "budget_ms",
                "instrument",
            },
            "workflow",
        )
        if data["schema"] != "shaderlod-workflow-v1":
            raise ValueError("unsupported workflow schema")
        scope = label(data["scope"], "scope")
        if scope not in {"profile", "development", "contribution", "release"}:
            raise ValueError("unsupported workflow scope")
        raw_arms = data["arms"]
        if not isinstance(raw_arms, list) or not 1 <= len(raw_arms) <= 16:
            raise ValueError("one to sixteen arms required")
        arms = tuple(label(arm, "arm") for arm in raw_arms)
        if len(set(arms)) != len(arms) or (scope != "profile" and len(arms) < 2):
            raise ValueError("distinct comparison arms required")
        blocks = positive(data["blocks"], "blocks")
        window = positive(data["window_ms"], "window_ms")
        budget = positive(data["budget_ms"], "budget_ms")
        if blocks > 100 or window > 300000 or budget > 86400000:
            raise ValueError("workflow exceeds supported finite bounds")
        instrument = label(data["instrument"], "instrument")
        if instrument not in {"frames", "diagnostic"}:
            raise ValueError("unknown instrument")
        if scope in {"contribution", "release"} and instrument != "frames":
            raise ValueError("qualification requires minimally instrumented outcomes")
        if len(arms) * blocks * window >= budget:
            raise ValueError("budget must leave time beyond capture for lifecycle work")
        return cls(
            scope,
            label(data["workload"], "workload"),
            arms,
            blocks,
            window,
            budget,
            instrument,
        )

    def describe(self) -> dict[str, object]:
        return {
            "schema": "shaderlod-workflow-plan-v1",
            "scope": self.scope,
            "workload": self.workload,
            "arms": list(self.arms),
            "blocks": self.blocks,
            "window_ms": self.window_ms,
            "capture_ms": len(self.arms) * self.blocks * self.window_ms,
            "budget_ms": self.budget_ms,
            "instrument": self.instrument,
            "live_capability": "not yet qualified",
            "acceptance": "no retention policy supplied",
        }


@dataclass(frozen=True)
class Frame:
    sequence: int
    timestamp_ns: int
    interval_ns: int
    generation: int

    def __post_init__(self) -> None:
        for name, value in (
            ("sequence", self.sequence),
            ("timestamp_ns", self.timestamp_ns),
            ("interval_ns", self.interval_ns),
            ("generation", self.generation),
        ):
            if (
                type(value) is not int
                or not (0 if name == "generation" else 1)
                <= value
                <= 9223372036854775807
            ):
                raise ValueError(
                    "frame field is outside its signed 64-bit contract: " + name
                )

    @classmethod
    def decode(cls, value: object) -> "Frame":
        data = object_fields(
            value, {"sequence", "timestamp_ns", "interval_ns", "generation"}, "frame"
        )
        generation = data["generation"]
        if type(generation) is not int or generation < 0:
            raise ValueError("nonnegative generation required")
        return cls(
            positive(data["sequence"], "sequence"),
            positive(data["timestamp_ns"], "timestamp_ns"),
            positive(data["interval_ns"], "interval_ns"),
            generation,
        )


def read_frames(path: Path, limit_bytes: int = 67108864) -> tuple[Frame, ...]:
    if path.stat().st_size > limit_bytes:
        raise ValueError("frame stream exceeds declared input limit")
    return decode_frames(path.read_bytes())


def decode_frames(payload: bytes) -> tuple[Frame, ...]:
    rows = []
    if len(payload) > 67108864:
        raise ValueError("frame stream exceeds supported limit")
    for line in payload.splitlines(keepends=True):
        if len(line) > 4096 or not line.endswith(b"\n"):
            raise ValueError("oversized or incomplete frame record")
        rows.append(Frame.decode(json.loads(line)))
    return tuple(rows)


def analyze_frames(frames: Iterable[Frame]) -> dict[str, object]:
    rows = tuple(frames)
    if not rows:
        raise ValueError("empty frame stream")
    generations = {row.generation for row in rows}
    missing = 0
    previous = None
    bins: dict[int, list[int]] = {}
    origin = rows[0].timestamp_ns - rows[0].interval_ns
    for row in rows:
        if previous is not None:
            if (
                row.sequence <= previous.sequence
                or row.timestamp_ns <= previous.timestamp_ns
            ):
                raise ValueError("frame sequence and time must increase")
            gap = row.sequence - previous.sequence - 1
            missing += gap
            if gap == 0 and row.timestamp_ns - previous.timestamp_ns != row.interval_ns:
                raise ValueError("frame interval disagrees with clock")
        elapsed = (row.timestamp_ns - origin - 1) // 1000000000
        bins.setdefault(elapsed, []).append(row.interval_ns)
        previous = row
    elapsed_ns = rows[-1].timestamp_ns - origin
    durations = sorted(row.interval_ns / 1000000 for row in rows)
    valid = missing == 0 and len(generations) == 1
    return {
        "schema": "shaderlod-frame-analysis-v1",
        "frames": len(rows),
        "elapsed_ns": elapsed_ns,
        "missing_frames": missing,
        "generations": sorted(generations),
        "valid": valid,
        "fps": len(rows) * 1000000000 / elapsed_ns if valid else None,
        "frame_ms_p50": durations[math.ceil(len(rows) * 0.5) - 1],
        "frame_ms_p95": durations[math.ceil(len(rows) * 0.95) - 1],
        "frame_ms_max": durations[-1],
        "tail_limit": "descriptive samples, not independent trials",
        "bins": [
            {
                "second": second,
                "frames": len(values),
                "observed_interval_ns": sum(values),
            }
            for second, values in sorted(bins.items())
        ],
        "scope": "application frame production; no GPU attribution or display guarantee",
    }


def import_capture(source: Path, destination: Path) -> dict[str, object]:
    if destination.exists():
        raise ValueError("fresh report directory required")
    if source.stat().st_size > 67108864:
        raise ValueError("frame input exceeds supported limit")
    payload = source.read_bytes()
    frames = decode_frames(payload)
    analysis = analyze_frames(frames)
    destination.mkdir(parents=True)
    publish_bytes(destination / "frames.jsonl", payload)
    publish_bytes(destination / "report.html", render_frames(frames, analysis).encode())
    publish(destination / "summary.json", analysis)
    identity = {
        "schema": "shaderlod-frame-import-v1",
        "source": str(source.resolve()),
        "sha256": hashlib.sha256(payload).hexdigest(),
        "bytes": len(payload),
        "evidence": "imported observations; provenance not independently qualified",
        "analysis": analysis,
    }
    publish(destination / "receipt.json", identity)
    return identity


def render_frames(frames: tuple[Frame, ...], analysis: dict[str, object]) -> str:
    origin = frames[0].timestamp_ns - frames[0].interval_ns
    points = [
        [(row.timestamp_ns - origin) / 1e9, row.interval_ns / 1e6, row.sequence]
        for row in frames
    ]
    data = json.dumps(points, allow_nan=False)
    summary = json.dumps(analysis, allow_nan=False).replace("<", "\\u003c")
    template = (Path(__file__).with_name("templates") / "frames.html").read_text()
    return template.replace("@@POINTS@@", data).replace("@@SUMMARY@@", summary)


def session_command(
    session: Path,
    action: str,
    duration_ms: int,
    timeout: float,
    payload: dict[str, object] | None = None,
) -> dict[str, object]:
    from shaderlod_host.runtime_live import executable_inputs
    from shaderlod_host.storage import BusyRefusal
    from shaderlod_host.worker import birth, boot

    metadata = json.loads((session / "session.json").read_bytes())
    if (
        metadata.get("schema") != "shaderlod-session-v1"
        or metadata["host"] != socket.gethostname()
    ):
        raise ValueError("foreign or unsupported session")
    if (
        metadata["boot"] != boot()
        or birth(metadata["owner_pid"]) != metadata["owner_birth"]
        or (session / "closed.json").exists()
    ):
        raise ValueError("session owner is not live")
    child_path = session / "child.json"
    if "child_record" in metadata and not child_path.exists():
        raise ValueError(
            "client ownership publication pending; retry status without replaying commands"
        )
    if child_path.exists():
        child = json.loads(child_path.read_bytes())
        if (
            child.get("host") != metadata["host"]
            or child.get("boot") != metadata["boot"]
            or birth(child["pid"]) != child["birth"]
        ):
            raise ValueError("recorded client process is not live")
        metadata["child"] = child
    launch_path = Path(metadata["launch"])
    launch = json.loads(launch_path.read_bytes())
    root = Path(__file__).resolve().parents[1]
    if (
        executable_inputs(launch, root, Path(metadata["profile"]))
        != metadata["executable_inputs"]
    ):
        raise ValueError("live executable input drift; restart session")
    if (
        action
        not in {
            "status",
            "capture",
            "close",
            "select",
            "restore",
            "prepare",
            "screenshot",
            "recover",
            "validate",
        }
        or type(duration_ms) is not int
        or not 0 <= duration_ms <= 300000
        or not 0 < timeout <= 310
    ):
        raise ValueError("invalid bounded session command")
    with BusyRefusal(session / "ownership", "command"):
        commands = sorted(session.glob("command-*.json"))
        sequence = len(commands) + 1
        terminal_failure = None
        if (session / "failure.json").exists():
            terminal_failure = json.loads((session / "failure.json").read_bytes())
        for failure_path in session.glob("failure-*.json"):
            candidate = json.loads(failure_path.read_bytes())
            if (
                not isinstance(candidate, dict)
                or type(candidate.get("sequence")) is not int
            ):
                raise ValueError("malformed controller failure identity")
            if (
                terminal_failure is None
                or candidate["sequence"] > terminal_failure["sequence"]
            ):
                terminal_failure = candidate
        prior_result = session / ("result-" + str(sequence - 1) + ".json")
        if isinstance(terminal_failure, dict) and prior_result.exists():
            prior = json.loads(prior_result.read_bytes())
            if prior.get("recovered_failure_sequence") == terminal_failure.get(
                "sequence"
            ):
                terminal_failure = None
        recover_close = (
            action in {"close", "recover"}
            and isinstance(terminal_failure, dict)
            and terminal_failure.get("sequence") == sequence - 1
        )
        if (
            commands
            and not (session / ("result-" + str(sequence - 1) + ".json")).exists()
            and not recover_close
        ):
            raise ValueError("prior command outcome unknown; refusing replay")
        if terminal_failure is not None and not recover_close:
            raise ValueError("session has a preserved controller failure")
        publish(
            session / ("command-" + str(sequence) + ".json"),
            {
                "schema": "shaderlod-control-v2",
                "sequence": sequence,
                "action": action,
                "duration_ms": duration_ms,
                "payload": {} if payload is None else payload,
            },
        )
        deadline = time.monotonic() + timeout
        result = session / ("result-" + str(sequence) + ".json")
        while not result.exists():
            if (
                (session / ("failure-" + str(sequence) + ".json")).exists()
                and not recover_close
            ) or (session / "closed.json").exists():
                raise CommandIncomplete(
                    "session failed or closed; inspect preserved evidence"
                )
            if time.monotonic() >= deadline:
                raise CommandIncomplete(
                    "command timed out; reconcile outcome before another command"
                )
            time.sleep(0.02)
        observed = json.loads(result.read_bytes())
        if (
            not isinstance(observed, dict)
            or observed.get("schema") != "shaderlod-control-result-v1"
            or observed.get("sequence") != sequence
        ):
            raise CommandIncomplete("command acknowledgement identity mismatch")
        if action == "close":
            while not (session / "closed.json").exists():
                if time.monotonic() >= deadline:
                    raise CommandIncomplete(
                        "close acknowledged; process finalization still pending"
                    )
                time.sleep(0.02)
            closed = json.loads((session / "closed.json").read_bytes())
            if (
                closed.get("returncode") != 0
                or closed.get("inputs_unchanged") is not True
                or closed.get("profile_artifact_restored") is not True
                or closed.get("shader_recovery_pending") is not False
                or closed.get("world_recovery_pending") is not False
            ):
                raise CommandIncomplete(
                    "session closed with an execution or artifact-restoration failure"
                )
            observed["closed"] = closed
        elif (
            executable_inputs(launch, root, Path(metadata["profile"]))
            != metadata["executable_inputs"]
        ):
            raise CommandIncomplete(
                "executable input drift during command; raw result retained in session"
            )
        for name, path in {
            "loaded_main_class_sha256": root
            / "build/classes/java/main/com/pp/shaderlod/storage/AtomicFiles.class",
            "loaded_dev_class_sha256": root
            / "build/classes/java/devClient/com/pp/shaderlod/dev/BenchmarkControl.class",
        }.items():
            if observed.get(name) != hashlib.sha256(path.read_bytes()).hexdigest():
                raise CommandIncomplete(
                    "loaded class disagrees with declared build: " + name
                )
        observed["session_identity"] = metadata
        return observed


def stage_summary(value: object) -> list[dict[str, object]]:
    if not isinstance(value, dict):
        return []
    groups: dict[tuple[str, str], dict[str, list[float]]] = {}
    for stream, field in (("cpu", "wall_ns"), ("gpu", "gpu_elapsed_ns")):
        rows = value.get(stream)
        if not isinstance(rows, list):
            raise ValueError("invalid stage stream")
        for row in rows:
            if (
                not isinstance(row, dict)
                or not isinstance(row.get("from"), str)
                or not isinstance(row.get("to"), str)
            ):
                raise ValueError("invalid stage boundary")
            raw = row.get(field)
            if type(raw) is not int or raw < 0:
                raise ValueError("invalid stage clock")
            group = groups.setdefault((row["from"], row["to"]), {"cpu": [], "gpu": []})
            group[stream].append(raw / 1000000)
    return [
        {
            "from": key[0],
            "to": key[1],
            "cpu_samples": len(group["cpu"]),
            "cpu_mean_ms": sum(group["cpu"]) / len(group["cpu"])
            if group["cpu"]
            else None,
            "gpu_samples": len(group["gpu"]),
            "gpu_mean_ms": sum(group["gpu"]) / len(group["gpu"])
            if group["gpu"]
            else None,
        }
        for key, group in groups.items()
    ]


def save_live_capture(
    observed: dict[str, object], destination: Path
) -> dict[str, object]:
    capture = observed.get("capture")
    if not isinstance(capture, dict) or not isinstance(capture.get("frames"), list):
        raise ValueError("missing capture records")
    frames = tuple(Frame.decode(row) for row in capture["frames"])
    analysis = analyze_frames(frames)
    analysis["benchmark_qualified"] = False
    analysis["events"] = observed.get("checkpoints", [])
    if "stage_profile" in observed:
        analysis["stage_summary"] = stage_summary(observed["stage_profile"])
        from shaderlod_host.adapters import semantic_mapping

        mapping = semantic_mapping(
            observed, Path(__file__).resolve().parents[1] / "benchmarks/mappings"
        )
        analysis["mapping"] = mapping
        profile = observed["stage_profile"]
        if not isinstance(profile, dict):
            raise ValueError("stage profile required")
        analysis["stage_health"] = {
            key: value for key, value in profile.items() if key not in {"cpu", "gpu"}
        }
        gpu = {row["span_id"]: row for row in profile["gpu"]}
        origin = frames[0].timestamp_ns - frames[0].interval_ns
        samples = []
        for row in profile["cpu"]:
            if "started_ns" not in row:
                continue
            semantic = "mixed / unmapped"
            definition = mapping.get("definition")
            if isinstance(definition, dict):
                for label_record in definition["labels"]:
                    if row["from"].startswith(label_record["namespace"]) and row[
                        "to"
                    ].startswith(label_record["namespace"]):
                        semantic = label_record["label"]
            samples.append(
                {
                    "start_s": (row["started_ns"] - origin) / 1e9,
                    "from": row["from"],
                    "to": row["to"],
                    "cpu_ms": row["wall_ns"] / 1e6,
                    "gpu_ms": gpu[row["span_id"]]["gpu_elapsed_ns"] / 1e6
                    if row["span_id"] in gpu
                    else None,
                    "submission": row["submission"],
                    "label": semantic,
                }
            )
        analysis["stage_samples"] = samples
        analysis["diagnostic_limits"] = (
            "Sampled stage intervals; missing GPU completions and shared shader effects prevent exclusive cost attribution"
        )
    if (
        observed.get("valid") is not True
        or capture.get("overflow") is not False
        or capture.get("generationChanged") is not False
        or observed.get("ready") is not True
    ):
        analysis["valid"] = False
        analysis["fps"] = None
    if destination.exists():
        raise ValueError("fresh output directory required")
    payload = b"".join(
        json.dumps(
            {
                "sequence": row.sequence,
                "timestamp_ns": row.timestamp_ns,
                "interval_ns": row.interval_ns,
                "generation": row.generation,
            }
        ).encode()
        + b"\n"
        for row in frames
    )
    destination.mkdir(parents=True)
    publish_bytes(destination / "frames.jsonl", payload)
    publish_bytes(destination / "report.html", render_frames(frames, analysis).encode())
    publish(destination / "summary.json", analysis)
    publish(destination / "observation.json", observed)
    publish(
        destination / "receipt.json",
        {
            "schema": "shaderlod-frame-capture-v1",
            "qualified": False,
            "files": {
                name: hashlib.sha256((destination / name).read_bytes()).hexdigest()
                for name in (
                    "frames.jsonl",
                    "summary.json",
                    "observation.json",
                    "report.html",
                )
            },
        },
    )
    return analysis


def verify_frame_receipt(path: Path) -> dict[str, object]:
    record = object_fields(
        json.loads(path.read_bytes()),
        {"schema", "qualified", "files"},
        "capture receipt",
    )
    if (
        record["schema"] != "shaderlod-frame-capture-v1"
        or record["qualified"] is not False
    ):
        raise ValueError("unsupported capture qualification or schema")
    files = object_fields(
        record["files"],
        {"frames.jsonl", "summary.json", "observation.json", "report.html"},
        "capture files",
    )
    for name, expected in files.items():
        asset = path.parent / name
        if (
            asset.is_symlink()
            or hashlib.sha256(asset.read_bytes()).hexdigest() != expected
        ):
            raise ValueError("capture digest disagreement: " + name)
    recomputed = analyze_frames(read_frames(path.parent / "frames.jsonl"))
    summary = json.loads((path.parent / "summary.json").read_bytes())
    observed = json.loads((path.parent / "observation.json").read_bytes())
    capture = observed.get("capture")
    if not isinstance(capture, dict) or not isinstance(capture.get("frames"), list):
        raise ValueError("missing original capture")
    if tuple(Frame.decode(row) for row in capture["frames"]) != read_frames(
        path.parent / "frames.jsonl"
    ):
        raise ValueError("capture/raw frame disagreement")
    if summary.get("valid") is True and (
        observed.get("valid") is not True
        or observed.get("ready") is not True
        or capture.get("overflow") is not False
        or capture.get("generationChanged") is not False
    ):
        raise ValueError("invalid observation promoted by summary")
    for field in (
        "frames",
        "elapsed_ns",
        "missing_frames",
        "generations",
        "frame_ms_max",
        "frame_ms_p50",
        "frame_ms_p95",
    ):
        if summary.get(field) != recomputed[field]:
            raise ValueError("capture analysis disagreement: " + field)
    if summary.get("valid") is True and (
        recomputed["valid"] is not True or summary.get("fps") != recomputed["fps"]
    ):
        raise ValueError("invalid stream promoted by summary")
    return {
        "schema": "shaderlod-capture-verification-v1",
        "integrity": "PASS",
        "benchmark_qualified": False,
        "scope": "file integrity and frame reduction only",
    }


def wait_ready(session: Path, timeout: float) -> dict[str, object]:
    prepared = False
    deadline = time.monotonic() + timeout
    while not (session / "session.json").exists():
        if time.monotonic() >= deadline or (session / "closed.json").exists():
            raise ValueError(
                "session startup did not publish ownership before deadline"
            )
        time.sleep(0.05)
    metadata = json.loads((session / "session.json").read_bytes())
    recover_needed = (
        Path(metadata["profile"]) / "shaderlod-benchmark-world.json"
    ).exists() and not any(session.glob("world-preimage-*.json"))
    while True:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise ValueError("readiness deadline exhausted")
        if "child_record" in metadata and not (session / "child.json").exists():
            if (session / "closed.json").exists():
                raise ValueError("session closed before child ownership publication")
            time.sleep(min(0.05, remaining))
            continue
        observed = session_command(session, "status", 0, min(65, remaining))
        if observed.get("world_loaded") is True and recover_needed:
            session_command(session, "recover", 0, min(65, remaining))
            recover_needed = False
            continue
        if observed.get("ready") is True:
            return observed
        if observed.get("world_loaded") is True and not prepared:
            session_command(
                session, "prepare", 0, min(65, max(0.1, deadline - time.monotonic()))
            )
            prepared = True
        time.sleep(min(0.2, max(0, deadline - time.monotonic())))


def build_identity(metadata: object) -> str | None:
    if not isinstance(metadata, dict):
        return None
    declared = metadata.get("build_sha256")
    if (
        isinstance(declared, str)
        and len(declared) == 64
        and all(c in "0123456789abcdef" for c in declared)
    ):
        return declared
    inputs = metadata.get("executable_inputs")
    if not isinstance(inputs, dict):
        return None
    matches = {
        value
        for path, value in inputs.items()
        if isinstance(path, str)
        and isinstance(value, str)
        and "/mods/shaderlod-" in path.replace("\\", "/").lower()
        and path.endswith(".jar")
    }
    return next(iter(matches)) if len(matches) == 1 else None

from dataclasses import dataclass
import hashlib
import json
import math
from pathlib import Path
import random
import time
from typing import Callable

from shaderlod_host.benchmark import (
    Frame,
    analyze_frames,
    object_fields,
    label,
    positive,
    session_command,
    save_live_capture,
)
from shaderlod_host.storage import publish, publish_bytes


def vector(value: object) -> tuple[float, ...]:
    if (
        not isinstance(value, list)
        or len(value) != 5
        or any(
            type(v) not in (int, float) or abs(v) > 1e12 or not math.isfinite(v)
            for v in value
        )
    ):
        raise ValueError("five finite pose coordinates required")
    result = tuple(float(v) for v in value)
    if (
        abs(result[0]) > 29000000
        or abs(result[2]) > 29000000
        or not -64 <= result[1] <= 1024
        or abs(result[4]) > 90
    ):
        raise ValueError("route outside admitted world bounds")
    return result


@dataclass(frozen=True)
class Case:
    identity: str
    pack: str
    sha256: str
    start: tuple[float, ...]
    end: tuple[float, ...]
    dimension: str
    surface: tuple[int, int]
    day_time: int = 6000
    weather: str = "clear"

    @classmethod
    def decode(cls, value: object) -> "Case":
        data = object_fields(
            value,
            {"id", "pack", "sha256", "from", "to", "dimension", "surface"}
            | (
                {"conditions"}
                if isinstance(value, dict) and "conditions" in value
                else set()
            ),
            "case",
        )
        pack = label(data["pack"], "pack")
        digest = label(data["sha256"], "sha256")
        if (
            "/" in pack
            or "\\" in pack
            or len(digest) != 64
            or any(c not in "0123456789abcdef" for c in digest)
        ):
            raise ValueError("regular pack filename and sha256 required")
        start, end = vector(data["from"]), vector(data["to"])
        if sum((end[i] - start[i]) ** 2 for i in range(3)) > 4096:
            raise ValueError("route exceeds 64 blocks")
        size = data["surface"]
        if not isinstance(size, list) or len(size) != 2:
            raise ValueError("native surface required")
        conditions = object_fields(
            data.get("conditions", {"day_time": 6000, "weather": "clear"}),
            {"day_time", "weather"},
            "conditions",
        )
        day = conditions["day_time"]
        if (
            type(day) is not int
            or not 0 <= day < 24000
            or not isinstance(conditions["weather"], str)
            or conditions["weather"] not in {"clear", "rain", "thunder"}
        ):
            raise ValueError("bounded fixed day time and supported weather required")
        return cls(
            label(data["id"], "case id"),
            pack,
            digest,
            start,
            end,
            label(data["dimension"], "dimension"),
            (positive(size[0], "width"), positive(size[1], "height")),
            day,
            str(conditions["weather"]),
        )


@dataclass(frozen=True)
class Arm:
    identity: str
    modules: tuple[str, ...]
    delay_ms: int

    @classmethod
    def decode(cls, value: object) -> "Arm":
        data = object_fields(value, {"id", "modules", "delay_ms"}, "arm")
        modules = data["modules"]
        delay = data["delay_ms"]
        if (
            not isinstance(modules, list)
            or type(delay) is not int
            or not 0 <= delay <= 100
        ):
            raise ValueError("module list and bounded explicit test delay required")
        ids = tuple(label(m, "module") for m in modules)
        if len(set(ids)) != len(ids):
            raise ValueError("duplicate modules")
        return cls(label(data["id"], "arm id"), ids, delay)


@dataclass(frozen=True)
class ComparisonPlan:
    scope: str
    cases: tuple[Case, ...]
    arms: tuple[Arm, ...]
    blocks: int
    window_ms: int
    warmup_ms: int
    budget_ms: int
    seed: int
    instrument: str = "frames"
    quality_cadence_ms: int = 0
    interaction: tuple[str, str, str, str] | None = None

    @classmethod
    def decode(cls, value: object) -> "ComparisonPlan":
        data = object_fields(
            value,
            {
                "schema",
                "scope",
                "cases",
                "arms",
                "blocks",
                "window_ms",
                "warmup_ms",
                "budget_ms",
                "seed",
            }
            | (
                {"instrument"}
                if isinstance(value, dict) and "instrument" in value
                else set()
            )
            | (
                {"interaction"}
                if isinstance(value, dict) and "interaction" in value
                else set()
            )
            | (
                {"quality_cadence_ms"}
                if isinstance(value, dict) and "quality_cadence_ms" in value
                else set()
            ),
            "comparison",
        )
        if (
            data["schema"] != "shaderlod-comparison-v1"
            or not isinstance(data["scope"], str)
            or data["scope"]
            not in {
                "development",
                "contribution",
                "release",
            }
        ):
            raise ValueError("unsupported comparison scope/schema")
        if (
            not isinstance(data["cases"], list)
            or not 1 <= len(data["cases"]) <= 64
            or not isinstance(data["arms"], list)
            or not 2 <= len(data["arms"]) <= 16
        ):
            raise ValueError("bounded cases and two or more arms required")
        cases = tuple(Case.decode(v) for v in data["cases"])
        arms = tuple(Arm.decode(v) for v in data["arms"])
        if len({c.identity for c in cases}) != len(cases) or len(
            {a.identity for a in arms}
        ) != len(arms):
            raise ValueError("duplicate case/arm identity")
        blocks = positive(data["blocks"], "blocks")
        window = positive(data["window_ms"], "window_ms")
        budget = positive(data["budget_ms"], "budget_ms")
        warmup, seed = data["warmup_ms"], data["seed"]
        if (
            blocks > 100
            or not 100
            <= window
            <= (60000 if data["scope"] == "development" else 300000)
            or budget > 86400000
            or type(warmup) is not int
            or not 0 <= warmup <= 60000
            or type(seed) is not int
            or seed < 0
        ):
            raise ValueError("invalid comparison limits or seed")
        if len(cases) * len(arms) * blocks * (window + warmup) >= budget:
            raise ValueError("budget needs lifecycle headroom")
        instrument = data.get("instrument", "frames")
        cadence = data.get("quality_cadence_ms", 0)
        if (
            not isinstance(instrument, str)
            or instrument not in {"frames", "stages", "memory-control"}
            or type(cadence) is not int
            or (cadence != 0 and not 100 <= cadence <= 1000)
        ):
            raise ValueError(
                "supported instrument and bounded quality cadence required"
            )
        if cadence and (window > 10000 or instrument != "frames"):
            raise ValueError("quality captures are separate and at most 10 seconds")
        if data["scope"] != "development" and (cadence or instrument != "frames"):
            raise ValueError(
                "qualification timings require minimal frame instrumentation"
            )
        interaction = None
        if "interaction" in data:
            members = data["interaction"]
            if (
                not isinstance(members, list)
                or len(members) != 4
                or not all(isinstance(item, str) for item in members)
                or len(set(members)) != 4
            ):
                raise ValueError(
                    "interaction needs four distinct original/incumbent/standalone/combined arm IDs"
                )
            by_id = {arm.identity: arm for arm in arms}
            if not set(members) <= by_id.keys():
                raise ValueError("interaction arms missing")
            original, incumbent, standalone, combined = (
                by_id[item] for item in members
            )
            if original.modules or set(combined.modules) != set(
                incumbent.modules
            ) | set(standalone.modules):
                raise ValueError(
                    "interaction module union differs from declared four cells"
                )
            interaction = (members[0], members[1], members[2], members[3])
        return cls(
            str(data["scope"]),
            cases,
            arms,
            blocks,
            window,
            warmup,
            budget,
            seed,
            str(instrument),
            cadence,
            interaction,
        )

    def schedule(self) -> tuple[tuple[int, Case, Arm], ...]:
        rng = random.Random(self.seed)
        case_order = list(self.cases)
        rng.shuffle(case_order)
        schedule: list[tuple[int, Case, Arm]] = []
        for case in case_order:
            arm_order = list(self.arms)
            rng.shuffle(arm_order)
            for block in range(self.blocks):
                ordered = arm_order if block % 2 == 0 else list(reversed(arm_order))
                schedule.extend((block, case, arm) for arm in ordered)
        return tuple(schedule)

    def wire(self) -> dict[str, object]:
        record: dict[str, object] = {
            "schema": "shaderlod-comparison-v1",
            "scope": self.scope,
            "cases": [
                {
                    "id": case.identity,
                    "pack": case.pack,
                    "sha256": case.sha256,
                    "from": list(case.start),
                    "to": list(case.end),
                    "dimension": case.dimension,
                    "surface": list(case.surface),
                    "conditions": {"day_time": case.day_time, "weather": case.weather},
                }
                for case in self.cases
            ],
            "arms": [
                {
                    "id": arm.identity,
                    "modules": list(arm.modules),
                    "delay_ms": arm.delay_ms,
                }
                for arm in self.arms
            ],
            "blocks": self.blocks,
            "window_ms": self.window_ms,
            "warmup_ms": self.warmup_ms,
            "budget_ms": self.budget_ms,
            "seed": self.seed,
            "instrument": self.instrument,
            "quality_cadence_ms": self.quality_cadence_ms,
        }

        if self.interaction is not None:
            record["interaction"] = list(self.interaction)
        return record

    def describe(self) -> dict[str, object]:
        return {
            "schema": "shaderlod-comparison-plan-v1",
            "scope": self.scope,
            "capture_ms": len(self.cases)
            * len(self.arms)
            * self.blocks
            * self.window_ms,
            "minimum_ms": len(self.cases)
            * len(self.arms)
            * self.blocks
            * (self.window_ms + self.warmup_ms),
            "budget_ms": self.budget_ms,
            "schedule": [
                {"block": block, "case": case.identity, "arm": arm.identity}
                for block, case, arm in self.schedule()
            ],
            "claim": "single-session exploratory comparison until independent qualification and acceptance policy supplied",
        }


def workload_failure(
    case: Case, observed: dict[str, object], window_ms: int
) -> str | None:
    if observed.get("progression_clock") != "client-simulation-ticks-20hz":
        return "unverified route progression clock"
    capture = observed.get("capture")
    if not isinstance(capture, dict) or not isinstance(capture.get("frames"), list):
        return "missing actual frame window"
    analysis = analyze_frames(tuple(Frame.decode(row) for row in capture["frames"]))
    measured_ms = float(str(analysis["elapsed_ns"])) / 1000000
    interval_limit = max(100, 2 * float(str(analysis["frame_ms_max"])))
    if abs(measured_ms - window_ms) > interval_limit:
        return "captured interval does not cover the requested window"
    ticks = observed.get("elapsed_client_ticks")
    expected = window_ms / 50
    if type(ticks) is not int or abs(ticks - expected) > max(2, expected * 0.02):
        return "simulation progression differs from declared workload"
    views = observed.get("view_checkpoints")
    if not isinstance(views, list) or not views:
        return "missing actual rendered-camera checkpoints"
    previous = 0
    gap_limit = max(500, interval_limit) * 1000000
    for view in views:
        if not isinstance(view, dict) or type(view.get("client_ticks")) is not int:
            return "malformed rendered-camera checkpoint"
        timestamp = view.get("elapsed_ns")
        if (
            type(timestamp) is not int
            or timestamp < previous
            or timestamp - previous > gap_limit
        ):
            return "incomplete rendered-camera checkpoint coverage"
        previous = timestamp
        pose = vector(view.get("player_pose"))
        camera = vector(view.get("camera_pose"))
        progress = min(1, max(0, view["client_ticks"] / expected))
        target = [
            case.start[i] + progress * (case.end[i] - case.start[i]) for i in range(5)
        ]
        if any(abs(pose[i] - target[i]) > (0.25 if i < 3 else 0.05) for i in range(5)):
            return "actual player pose differs from scheduled route"
        eye = view.get("eye_height")
        if (
            not isinstance(eye, (int, float))
            or isinstance(eye, bool)
            or view.get("first_person") is not True
        ):
            return "unsupported camera mode or eye state"
        camera_target = [pose[0], pose[1] + eye, pose[2]]
        for i in range(3):
            tolerance = abs(case.end[i] - case.start[i]) / expected + 0.25
            if abs(camera[i] - camera_target[i]) > tolerance:
                return "rendered camera differs from admitted route"
    if window_ms * 1000000 - previous > gap_limit:
        return "rendered-camera checkpoints ended before workload"
    return None


def execute_comparison(
    plan: ComparisonPlan,
    session: Path,
    output: Path,
    command: Callable[..., dict[str, object]] = session_command,
    policy: dict[str, object] | None = None,
) -> dict[str, object]:
    if output.exists():
        raise ValueError("fresh comparison output required")
    output.mkdir(parents=True)
    publish(
        output / "plan.json", {"definition": plan.wire(), "resolved": plan.describe()}
    )
    policy_identity = None
    if policy is not None:
        from shaderlod_host.assessment import QualificationPolicy

        declared = QualificationPolicy.decode(policy)
        policy_identity = declared.identity
        publish(output / "policy.json", declared.wire())
    started = time.monotonic()
    deadline = started + plan.budget_ms / 1000
    execution_deadline = deadline - min(30, plan.budget_ms / 3000)
    results: list[dict[str, object]] = []
    failure = None
    attempted: list[dict[str, object]] = []
    restored = False
    inputs: dict[str, str] = {}
    baselines: dict[str, dict[str, object]] = {}

    def call(
        action: str, duration: int = 0, payload: dict[str, object] | None = None
    ) -> dict[str, object]:
        remaining = execution_deadline - time.monotonic()
        if remaining <= 0:
            raise ValueError("comparison budget exhausted")
        return command(
            session,
            action,
            duration,
            min(310 if action == "capture" else 65, remaining),
            payload,
        )

    try:
        initial = call("status")
        metadata = initial.get("session_identity")
        if isinstance(metadata, dict):
            profile = Path(str(metadata["profile"]))
            for case in plan.cases:
                source = profile / "shaderpacks" / case.pack
                if source.is_symlink():
                    raise ValueError("original archive cannot be a symlink")
                payload = source.read_bytes()
                if (
                    source.is_symlink()
                    or hashlib.sha256(payload).hexdigest() != case.sha256
                ):
                    raise ValueError("original archive preflight identity disagreement")
                name = "inputs/" + case.sha256 + ".zip"
                if name not in inputs:
                    publish_bytes(output / name, payload)
                    inputs[name] = case.sha256
        if initial.get("ready") is not True and initial.get("world_loaded") is not True:
            raise ValueError(
                "session is not ready; wait for ready status before comparison"
            )
        for index, (block, case, arm) in enumerate(plan.schedule()):
            case_dir = output / ("attempt-" + str(index + 1))
            attempt = {
                "case": case.identity,
                "arm": arm.identity,
                "block": block,
                "directory": str(case_dir.resolve()),
                "started_seconds": time.monotonic() - started,
            }
            attempted.append(attempt)
            publish(output / ("attempt-" + str(index + 1) + ".started.json"), attempt)
            call(
                "prepare",
                payload={
                    "day_time": case.day_time,
                    "weather": case.weather,
                    "pose": list(case.start),
                },
            )
            if case.identity not in baselines:
                native = initial
                initial_activation = initial.get("activation")
                if (
                    not isinstance(initial_activation, dict)
                    or initial_activation.get("archiveSha256") != case.sha256
                    or initial.get("selected_modules", []) != []
                ):
                    native = call(
                        "select",
                        payload={
                            "pack": case.pack,
                            "sha256": case.sha256,
                            "modules": [],
                        },
                    )
                baselines[case.identity] = native
            selection_started = time.monotonic()
            selected = call(
                "select",
                payload={
                    "pack": case.pack,
                    "sha256": case.sha256,
                    "modules": list(arm.modules),
                },
            )
            selection_seconds = time.monotonic() - selection_started
            if configuration(selected) != configuration(baselines[case.identity]):
                raise ValueError(
                    "candidate changed native options, surface, runtime, resources or DH configuration"
                )
            activation = selected.get("activation")
            if (
                not isinstance(activation, dict)
                or activation.get("linked") is not True
                or not any(
                    str(w).startswith("submitted-frame:")
                    for w in activation.get("witnesses", [])
                )
            ):
                raise ValueError("missing actual submitted activation")
            if (
                selected.get("surface") != list(case.surface)
                or selected.get("dimension") != case.dimension
                or selected.get("ready") is not True
            ):
                raise ValueError("surface, dimension or readiness differs from case")
            conditions_started = time.monotonic()
            conditions_state = selected
            while not conditions_match(case, conditions_state):
                if time.monotonic() - conditions_started >= 10:
                    raise ValueError(
                        "declared weather/time did not settle within fixed allowance"
                    )
                time.sleep(0.05)
                conditions_state = call("status")
            conditions_seconds = time.monotonic() - conditions_started
            if plan.warmup_ms:
                if execution_deadline - time.monotonic() <= plan.warmup_ms / 1000:
                    raise ValueError("insufficient remaining warmup budget")
                time.sleep(plan.warmup_ms / 1000)
            conditioned = call("status")
            pose = vector(conditioned.get("pose"))
            if any(
                abs(pose[i] - case.start[i]) > (0.25 if i < 3 else 0.05)
                for i in range(5)
            ):
                raise ValueError(
                    "prepared player drifted during fixed conditioning; use an appropriate prepared scene"
                )
            capture_payload: dict[str, object] = {
                "from": list(case.start),
                "to": list(case.end),
                "delay_ms": arm.delay_ms,
            }
            if plan.instrument == "stages":
                capture_payload["diagnostic"] = True
            if plan.instrument == "memory-control":
                capture_payload["durable_chunks"] = False
            quality = None
            if plan.quality_cadence_ms:
                capture_payload["quality_cadence_ms"] = plan.quality_cadence_ms
            window_started = time.monotonic() - started
            observed = call(
                "capture",
                plan.window_ms,
                capture_payload,
            )
            summary = save_live_capture(observed, case_dir)
            if plan.quality_cadence_ms:
                from shaderlod_host.quality import save_sequence

                quality = save_sequence(
                    observed, session, case_dir, plan.quality_cadence_ms, plan.window_ms
                )
            if arm.delay_ms:
                elapsed_delay = observed.get("executed_delay_ns")
                if (
                    type(elapsed_delay) is not int
                    or elapsed_delay
                    < positive(summary["frames"], "frames") * arm.delay_ms * 1000000
                ):
                    raise ValueError(
                        "known slowdown did not execute its declared delay"
                    )
            route_failure = workload_failure(case, observed, plan.window_ms)
            if isinstance(quality, dict) and quality.get("sequence_valid") is not True:
                route_failure = (
                    route_failure
                    or "quality cadence, delivery or camera alignment incomplete"
                )
            captured_activation = observed.get("activation")
            activation_matches = (
                isinstance(captured_activation, dict)
                and all(
                    captured_activation.get(key) == activation.get(key)
                    for key in ("archiveSha256", "generation", "packName")
                )
                and summary.get("generations") == [selected.get("generation")]
            )
            row: dict[str, object] = {
                "workload_valid": route_failure is None,
                "workload_failure": route_failure,
                "case": case.identity,
                "arm": arm.identity,
                "block": block,
                "session": str(session.resolve()),
                "attempt": case_dir.name,
                "summary": summary,
                "selection": selected,
                "delay_ms": arm.delay_ms,
                "instrument": plan.instrument,
                "quality_only": plan.quality_cadence_ms > 0,
                "selection_seconds": selection_seconds,
                "conditions_seconds": conditions_seconds,
                "conditioning": conditioned,
                "window_started_seconds": window_started,
                "window_ended_seconds": time.monotonic() - started,
            }
            results.append(row)
            publish(case_dir / "comparison.json", row)
            if (
                route_failure is not None
                or summary["valid"] is not True
                or not activation_matches
                or selected.get("selected_modules", []) != list(arm.modules)
                or observed.get("selected_modules", []) != list(arm.modules)
                or observed.get("surface") != list(case.surface)
                or observed.get("dimension") != case.dimension
                or not conditions_match(case, observed)
                or observed.get("options") != selected.get("options")
                or configuration(observed) != configuration(selected)
            ):
                raise ValueError("invalid measured window or configuration drift")
    except (OSError, ValueError, RuntimeError) as error:
        failure = str(error)
    finally:
        try:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise ValueError(
                    "no remaining teardown budget; recovery journal retained"
                )
            command(session, "restore", 0, min(60, remaining), None)
            restored = True
        except (OSError, ValueError, RuntimeError) as error:
            failure = (failure or "") + "; restoration failed: " + str(error)
    result: dict[str, object] = {
        "schema": "shaderlod-comparison-result-v1",
        "scope": plan.scope,
        "started_unix_ns": time.time_ns()
        - int((time.monotonic() - started) * 1000000000),
        "protocol_sha256": hashlib.sha256(
            json.dumps(plan.wire(), sort_keys=True).encode()
        ).hexdigest(),
        "state": "complete" if failure is None else "incomplete",
        "elapsed_seconds": time.monotonic() - started,
        "restored": restored,
        "failure": failure,
        "policy_sha256": policy_identity,
        "input_archives": inputs,
        "baselines": baselines,
        "observations": results,
        "attempts": attempted,
        "reliability": {
            "attempted": len(attempted),
            "captured": len(results),
            "required": len(plan.schedule()),
        },
        "interactions": interaction_effects(results, plan.interaction)
        if plan.interaction
        else [],
        "qualification": "unqualified",
        "retention": "unresolved: independent-session/coverage/quality and acceptance policy required",
    }
    publish(output / "result.json", result)
    publish_bytes(output / "report.html", render_comparison(result).encode())
    publish(
        output / "receipt.json",
        {
            "schema": "shaderlod-comparison-receipt-v1",
            "sha256": hashlib.sha256((output / "result.json").read_bytes()).hexdigest(),
            "qualified": False,
        },
    )
    return result


def render_comparison(result: dict[str, object]) -> str:
    data = json.dumps(result, allow_nan=False).replace("<", "\\u003c")
    template = (Path(__file__).with_name("templates") / "comparison.html").read_text()
    return template.replace("@@DATA@@", data)


def interaction_effects(
    rows: list[dict[str, object]], arms: tuple[str, str, str, str]
) -> list[dict[str, object]]:
    grouped: dict[tuple[str, str], dict[str, float]] = {}
    for row in rows:
        summary = row.get("summary")
        if (
            not isinstance(summary, dict)
            or row.get("workload_valid") is not True
            or summary.get("valid") is not True
        ):
            continue
        fps = summary.get("fps")
        if not isinstance(fps, (int, float)) or fps <= 0:
            continue
        grouped.setdefault((str(row["case"]), str(row["block"])), {})[
            str(row["arm"])
        ] = 1000 / fps
    output: list[dict[str, object]] = []
    for (case, block), times in grouped.items():
        if not set(arms) <= times.keys():
            output.append(
                {"case": case, "block": block, "state": "missing four-cell evidence"}
            )
            continue
        original, incumbent, standalone, combined = (times[arm] for arm in arms)
        output.append(
            {
                "case": case,
                "block": block,
                "state": "observed",
                "interaction_ms": (combined - incumbent) - (standalone - original),
                "mean_frame_ms": times,
                "meaning": "Positive means less-than-additive time reduction; descriptive block effect, no independence or higher-order guarantee",
            }
        )
    return output


def conditions_match(case: Case, observed: dict[str, object]) -> bool:
    rain = observed.get("rain")
    thunder = observed.get("thunder", 0)
    if (
        not isinstance(rain, (int, float))
        or not isinstance(thunder, (int, float))
        or observed.get("world_day_time") != case.day_time
    ):
        return False
    return (
        rain <= 0.01 and thunder <= 0.01
        if case.weather == "clear"
        else rain >= 0.99
        and (thunder >= 0.99 if case.weather == "thunder" else thunder <= 0.01)
    )


def verify_comparison(path: Path) -> dict[str, object]:
    from shaderlod_host.benchmark import verify_frame_receipt

    result = json.loads(path.read_bytes())
    receipt = json.loads((path.parent / "receipt.json").read_bytes())
    if (
        not isinstance(result, dict)
        or result.get("schema") != "shaderlod-comparison-result-v1"
        or receipt.get("sha256") != hashlib.sha256(path.read_bytes()).hexdigest()
    ):
        raise ValueError("comparison receipt/schema disagreement")
    archives = result.get("input_archives", {})
    if not isinstance(archives, dict):
        raise ValueError("input archive map required")
    for name, expected in archives.items():
        asset = path.parent / name
        if (
            name != "inputs/" + str(expected) + ".zip"
            or asset.is_symlink()
            or not asset.resolve().is_relative_to(path.parent.resolve())
            or hashlib.sha256(asset.read_bytes()).hexdigest() != expected
        ):
            raise ValueError("preserved original archive identity disagreement")
    definition = json.loads((path.parent / "plan.json").read_bytes())["definition"]
    plan = ComparisonPlan.decode(definition)
    if (
        result.get("protocol_sha256")
        != hashlib.sha256(json.dumps(definition, sort_keys=True).encode()).hexdigest()
    ):
        raise ValueError("frozen comparison protocol disagreement")
    rows = result.get("observations")
    schedule = plan.schedule()
    if (
        not isinstance(rows, list)
        or len(rows) > len(schedule)
        or (result.get("state") == "complete" and len(rows) != len(schedule))
    ):
        raise ValueError("comparison coverage differs from frozen schedule")
    for row, (block, case, arm) in zip(rows, schedule):
        if not isinstance(row, dict) or (
            row.get("case"),
            row.get("arm"),
            row.get("block"),
        ) != (case.identity, arm.identity, block):
            raise ValueError("observation differs from scheduled arm/case/block")
        directory = path.parent / str(row.get("attempt"))
        verify_frame_receipt(directory / "receipt.json")
        summary = json.loads((directory / "summary.json").read_bytes())
        observed = json.loads((directory / "observation.json").read_bytes())
        if row.get("summary") != summary:
            raise ValueError("comparison summary disagrees with captured evidence")
        if (
            row.get("workload_valid") is True
            and workload_failure(case, observed, plan.window_ms) is not None
        ):
            raise ValueError("invalid route promoted by comparison")
        if result.get("state") != "complete":
            continue
        selected = row.get("selection")
        if (
            not isinstance(selected, dict)
            or selected.get("surface") != list(case.surface)
            or selected.get("dimension") != case.dimension
            or not conditions_match(case, observed)
        ):
            raise ValueError("comparison environment differs from declared case")
        baseline = result.get("baselines", {}).get(case.identity)
        if isinstance(baseline, dict) and configuration(selected) != configuration(
            baseline
        ):
            raise ValueError("candidate differs from native configuration baseline")
        if configuration(observed) != configuration(selected):
            raise ValueError("configuration drift during captured window")
        activation = selected.get("activation")
        actual = observed.get("activation")
        if (
            not isinstance(activation, dict)
            or not isinstance(actual, dict)
            or activation.get("linked") is not True
            or any(
                actual.get(key) != activation.get(key)
                for key in ("archiveSha256", "generation", "packName")
            )
            or summary.get("generations") != [selected.get("generation")]
        ):
            raise ValueError("comparison activation/generation join failed")
        digest = activation.get("archiveSha256")
        witnesses = activation.get("witnesses")
        if (
            not isinstance(witnesses, list)
            or not all(isinstance(item, str) for item in witnesses)
            or set(witnesses)
            != {"linked-archive:" + str(digest), "submitted-frame:" + str(digest)}
        ):
            raise ValueError("actual submitted activation witnesses missing")
        if not arm.modules and digest != case.sha256:
            raise ValueError("original archive differs from case")
        if selected.get("selected_modules", []) != list(arm.modules) or observed.get(
            "selected_modules", []
        ) != list(arm.modules):
            raise ValueError("requested modules were not actually prepared")
    return result


def configuration(observed: dict[str, object]) -> dict[str, object]:
    dh = observed.get("dh")
    if (
        isinstance(dh, dict)
        and dh.get("present") is True
        and type(dh.get("enabled")) is not bool
    ):
        raise ValueError("DH configured state is unknown")
    return {
        "surface": observed.get("surface"),
        "dimension": observed.get("dimension"),
        "options": observed.get("options"),
        "client_options": observed.get("client_options"),
        "resource_packs": observed.get("resource_packs"),
        "dh": {key: dh.get(key) for key in ("present", "version", "enabled")}
        if isinstance(dh, dict)
        else None,
        "runtime": observed.get("runtime"),
        "renderer": observed.get("renderer"),
    }


def installation_plan(plan: ComparisonPlan) -> dict[str, object]:
    if (
        len(plan.cases) != 1
        or tuple(arm.identity for arm in plan.arms) != ("native", "installed-Off")
        or any(arm.modules or arm.delay_ms for arm in plan.arms)
        or plan.instrument != "frames"
        or plan.quality_cadence_ms
        or plan.window_ms > 60000
    ):
        raise ValueError(
            "installation needs one case, native/installed-Off empty arms and frame-only windows up to 60 seconds"
        )
    return plan.describe() | {
        "fresh_processes": 2 * plan.blocks,
        "mode": "native / installed-Off",
        "startup_and_close_allowance_seconds_per_process": 135,
    }


def verify_installation(path: Path) -> dict[str, object]:
    from shaderlod_host.benchmark import verify_frame_receipt

    result = json.loads(path.read_bytes())
    receipt = json.loads((path.parent / "receipt.json").read_bytes())
    if (
        not isinstance(result, dict)
        or result.get("schema") != "shaderlod-installation-result-v1"
        or receipt.get("sha256") != hashlib.sha256(path.read_bytes()).hexdigest()
    ):
        raise ValueError("installation result/receipt disagreement")
    plan = ComparisonPlan.decode(
        json.loads((path.parent / "plan.json").read_bytes())["definition"]
    )
    installation_plan(plan)
    rows = result.get("observations")
    if not isinstance(rows, list) or (
        result.get("state") == "complete" and len(rows) != 2 * plan.blocks
    ):
        raise ValueError("installation process coverage incomplete")
    for row in rows:
        directory = path.parent / row["capture"]
        verify_frame_receipt(directory / "receipt.json")
        observed = json.loads((directory / "observation.json").read_bytes())
        if (
            row["summary"] != json.loads((directory / "summary.json").read_bytes())
            or (observed["runtime_mods"].get("shaderlod") == "absent")
            != (row["mode"] == "native")
            or workload_failure(plan.cases[0], observed, plan.window_ms) is not None
        ):
            raise ValueError(
                "installation evidence does not match declared mode/workload"
            )
    return result
